const SYLLABUS_A1 = [
  {"n":1,"module":1,"id":"syl-a1-01","title":"Hello! Meeting people","emoji":"👋","description":"Say hello, introduce yourself, say where you're from and spell your name","goals":["I can greet people and introduce myself.","I can ask What's your name? and Where are you from?","I can use am, is and are with I, you, he and she.","I can spell my name and ask someone to repeat."],"grammarTip":"The verb be has three forms in the present: I am, he / she is, you are. In conversation we use the short forms: I'm, he's, she's, you're. For a question, put the verb first: Are you from Chile? Where is she from?","rules":[{"label":"I","form":"am","hint":"Only with I. Short form: I'm.","examples":["I am Nina.","I am from Brazil.","I am a designer."]},{"label":"he / she","form":"is","hint":"With he, she and one person. Short form: he's, she's.","examples":["She is from Taiwan.","He is a nurse.","Omar is from Jordan."]},{"label":"you","form":"are","hint":"With you. Short form: you're. Question: Are you…?","examples":["You are my new classmate.","Where are you from?","Are you Jack?"]}],"words":[{"id":"hello","en":"hello","pt":"olá","emoji":"👋"},{"id":"hi","en":"hi","pt":"oi","emoji":"🙋"},{"id":"goodmorning","en":"good morning","pt":"bom dia","emoji":"🌅"},{"id":"goodafternoon","en":"good afternoon","pt":"boa tarde","emoji":"🌤️"},{"id":"goodevening","en":"good evening","pt":"boa noite (ao chegar)","emoji":"🌆"},{"id":"goodbye","en":"goodbye","pt":"tchau","emoji":"🚪"},{"id":"name","en":"name","pt":"nome","emoji":"🪪"},{"id":"surname","en":"surname","pt":"sobrenome","emoji":"🔤"},{"id":"country","en":"country","pt":"país","emoji":"🌎"},{"id":"brazil","en":"Brazilian","pt":"brasileiro(a)","emoji":"🇧🇷"},{"id":"irish","en":"Irish","pt":"irlandês / irlandesa","emoji":"🇮🇪"},{"id":"spell","en":"spell","pt":"soletrar","emoji":"🔡"},{"id":"repeat","en":"repeat","pt":"repetir","emoji":"🔁"},{"id":"classmate","en":"classmate","pt":"colega de turma","emoji":"🧑‍🤝‍🧑"}],"chunks":[{"en":"Nice to meet you.","pt":"Prazer em conhecer."},{"en":"My name's… / I'm…","pt":"Meu nome é… / Eu sou…"},{"en":"Where are you from?","pt":"De onde você é?"},{"en":"How do you spell that?","pt":"Como se soletra?"},{"en":"Can you repeat that, please?","pt":"Pode repetir, por favor?"},{"en":"What about you?","pt":"E você?"}],"social":{"skill":"Greet someone new and ask them to repeat","tip":"When you meet someone, say Nice to meet you and ask a question back: What about you? If you don't understand, it's OK. Say Sorry, can you repeat that, please?","dialogue":[{"who":"Jack","line":"Hi! I'm Jack. What's your name?"},{"who":"Mei","line":"Hi, Jack. I'm Mei. ___","gap":"Nice to meet you.","options":["Nice to meet you.","Goodbye.","I'm fine."]},{"who":"Jack","line":"Nice to meet you too. Where are you from?"},{"who":"Mei","line":"I'm from Taiwan. ___","gap":"What about you?","options":["What about you?","How old are you?","Where is it?"]},{"who":"Jack","line":"I'm from Dublin, in Ireland."},{"who":"Mei","line":"Sorry, ___","gap":"can you repeat that, please?","options":["can you repeat that, please?","you are welcome.","see you later."]},{"who":"Jack","line":"Dublin. D-U-B-L-I-N. It's in Ireland."},{"who":"Mei","line":"Oh, Dublin! ___ Mei is M-E-I.","gap":"How do you spell your name?","options":["How do you spell your name?","Where are you from?","What do you do?"]}]},"mistakes":[{"wrong":"I from Brazil.","options":["I'm from Brazil.","I is from Brazil.","I from am Brazil."],"right":"I'm from Brazil.","why":"O verbo be não some em inglês: I am (I'm) from Brazil."},{"wrong":"She are from Ireland.","options":["She is from Ireland.","She am from Ireland.","She be from Ireland."],"right":"She is from Ireland.","why":"Com he / she usamos is."},{"wrong":"Where you are from?","options":["Where are you from?","Where you from are?","Where is you from?"],"right":"Where are you from?","why":"Na pergunta, o verbo vem antes de you: Where are you…?"},{"wrong":"My name is Nina Alves, I am brazilian.","options":["My name is Nina Alves. I'm Brazilian.","My name is Nina Alves. I'm brazilian.","My name is Nina Alves. I Brazilian."],"right":"My name is Nina Alves. I'm Brazilian.","why":"Nacionalidades começam com letra maiúscula em inglês: Brazilian, Irish."},{"wrong":"Nice to know you.","options":["Nice to meet you.","Nice to see you first.","Nice know you."],"right":"Nice to meet you.","why":"Para alguém que você acabou de conhecer: Nice to meet you."},{"wrong":"Good night! I'm Omar. I'm your new classmate.","options":["Good evening! I'm Omar. I'm your new classmate.","Good morning night! I'm Omar.","Night! I'm Omar, your new classmate."],"right":"Good evening! I'm Omar. I'm your new classmate.","why":"Good night é para se despedir ou ir dormir. Ao chegar à noite: Good evening."}],"pron":{"focus":"The alphabet: letters with the same sound","tip":"Many letters share a vowel sound. A, H, J, K sound like 'day'. B, C, D, E, G, P, T, V sound like 'see'. Listen to each letter and put it in the right group.","type":"sort","buckets":["A H J K (day)","B C D E G P T V (see)","F L M N S X (yes)"],"items":[{"text":"A","say":"the letter A","bucket":"A H J K (day)"},{"text":"H","say":"the letter H","bucket":"A H J K (day)"},{"text":"J","say":"the letter J","bucket":"A H J K (day)"},{"text":"K","say":"the letter K","bucket":"A H J K (day)"},{"text":"B","say":"the letter B","bucket":"B C D E G P T V (see)"},{"text":"E","say":"the letter E","bucket":"B C D E G P T V (see)"},{"text":"G","say":"the letter G","bucket":"B C D E G P T V (see)"},{"text":"V","say":"the letter V","bucket":"B C D E G P T V (see)"},{"text":"F","say":"the letter F","bucket":"F L M N S X (yes)"},{"text":"M","say":"the letter M","bucket":"F L M N S X (yes)"},{"text":"S","say":"the letter S","bucket":"F L M N S X (yes)"},{"text":"X","say":"the letter X","bucket":"F L M N S X (yes)"}]},"practiceSentences":["Hi, my name is Omar","I am from Jordan","She is from Taiwan","Where are you from","Nice to meet you","How do you spell your name","Can you repeat that, please","He is my new classmate","Are you from Ireland"],"readingTime":{"text":"New in class: say hello!\nHello! My name's Nina Alves. I'm Brazilian. I'm from Recife, but I live in Porto Alegre now. I'm a designer.\nHi, everyone! I'm Omar Haddad. I'm from Amman, in Jordan. I'm a nurse in Toronto, Canada. My surname is H-A-D-D-A-D.\nGood evening from Taipei! I'm Mei Lin. I'm Taiwanese. It's 9 pm here, so this is my evening class.\nHi! I'm Jack Moore. I'm Irish, from Dublin. I'm a tour guide. Nice to meet you all!","questions":[{"prompt":"Where is Nina from?","options":["Porto Alegre","Recife","Toronto"],"correct":"Recife"},{"prompt":"Who is a nurse?","options":["Omar","Jack","Mei"],"correct":"Omar"}]},"quiz":[{"prompt":"I ___ from Chile.","options":["am","is","are"],"correct":"am","explain":"With I we use am."},{"prompt":"Mei ___ from Taiwan.","options":["am","is","are"],"correct":"is","explain":"One person (she) takes is."},{"prompt":"Where ___ you from?","options":["am","is","are"],"correct":"are","explain":"With you we use are."},{"prompt":"You meet someone for the first time. You say…","options":["Nice to meet you.","See you later.","Good night."],"correct":"Nice to meet you."},{"prompt":"You don't understand. You say…","options":["Can you repeat that, please?","What about you?","Goodbye."],"correct":"Can you repeat that, please?"},{"prompt":"Jack is from Ireland. He is…","options":["Irish","Irland","Ireland"],"correct":"Irish"}],"writingPrompt":{"prompt":"Write a short message to your new class: say hello, your name, where you are from and what you do.","help":["Hello! My name's…","I'm from…","I live in…","I'm a / an…"],"words":30}},
  {"n":2,"module":1,"id":"syl-a1-02","title":"People and jobs","emoji":"💼","description":"Talk about jobs and age, use be with all people and show interest when someone talks","goals":["I can say what I do and ask What do you do?","I can use am, is and are with I, you, he, she, it, we and they.","I can make negatives and questions with be: isn't, aren't, Is she…?","I can ask How old are you? and show interest: Really? That's interesting!"],"grammarTip":"Be has three forms: I am, he / she / it is, you / we / they are. For the negative, add not: I'm not, he isn't, they aren't. For a question, put the verb first: Is she a nurse? Are they from Spain? With jobs, use a or an: a nurse, an engineer.","rules":[{"label":"we / you / they","form":"are","hint":"With more than one person. Short form: we're, you're, they're.","examples":["We are classmates.","They are from Spain.","Are you a teacher?"]},{"label":"negative: he / she / it","form":"isn't","hint":"is + not = isn't. Also: she's not.","examples":["Jack isn't a nurse.","She isn't from Canada.","My job isn't easy."]},{"label":"negative: we / you / they","form":"aren't","hint":"are + not = aren't. Also: they're not.","examples":["We aren't doctors.","They aren't from Ireland.","You aren't late."]},{"label":"negative: I","form":"I'm not","hint":"With I, say I'm not. (Not I amn't!)","examples":["I'm not a student.","I'm not from Lisbon.","I'm not thirty, I'm twenty-nine!"]}],"words":[{"id":"job","en":"job","pt":"trabalho, emprego","emoji":"💼"},{"id":"doctor","en":"doctor","pt":"médico(a)","emoji":"🩺"},{"id":"nurse","en":"nurse","pt":"enfermeiro(a)","emoji":"🧑‍⚕️"},{"id":"teacher","en":"teacher","pt":"professor(a)","emoji":"🧑‍🏫"},{"id":"student","en":"student","pt":"estudante","emoji":"🎒"},{"id":"designer","en":"designer","pt":"designer","emoji":"🎨"},{"id":"engineer","en":"engineer","pt":"engenheiro(a)","emoji":"👷"},{"id":"tourguide","en":"tour guide","pt":"guia de turismo","emoji":"🗺️"},{"id":"waiter","en":"waiter","pt":"garçom","emoji":"🍽️"},{"id":"driver","en":"driver","pt":"motorista","emoji":"🚌"},{"id":"hospital","en":"hospital","pt":"hospital","emoji":"🏥"},{"id":"office","en":"office","pt":"escritório","emoji":"🏢"},{"id":"bank","en":"bank","pt":"banco","emoji":"🏦"},{"id":"yearsold","en":"years old","pt":"anos (de idade)","emoji":"🎂"}],"chunks":[{"en":"What do you do?","pt":"O que você faz? (profissão)"},{"en":"I'm a… / I'm an…","pt":"Eu sou… (profissão)"},{"en":"Where do you work?","pt":"Onde você trabalha?"},{"en":"How old are you?","pt":"Quantos anos você tem?"},{"en":"Really? That's interesting!","pt":"Sério? Que interessante!"},{"en":"Oh, cool! / That's great!","pt":"Ah, legal! / Que ótimo!"}],"social":{"skill":"Show interest: Really? That's interesting!","tip":"When someone tells you about their life, show interest. Say Really? That's interesting! or Oh, cool! Then ask one more question.","dialogue":[{"who":"Nina","line":"So, Omar, what do you do?"},{"who":"Omar","line":"I'm a nurse. I'm at a big hospital in Toronto."},{"who":"Nina","line":"___ Is it a hard job?","gap":"Really? That's interesting!","options":["Really? That's interesting!","Oh no, I'm sorry.","Nice to meet you."]},{"who":"Omar","line":"Sometimes, yes. Some weeks I'm at the hospital at night. What about you?"},{"who":"Nina","line":"I'm a UX designer. I design apps."},{"who":"Omar","line":"___ Is your company big?","gap":"Oh, cool!","options":["Oh, cool!","Oh, sorry!","Goodbye!"]},{"who":"Nina","line":"No, it isn't. We're only twelve people. And on Mondays and Fridays I'm at home."},{"who":"Omar","line":"At home? ___","gap":"That's great!","options":["That's great!","That's terrible!","You're welcome!"]},{"who":"Nina","line":"Yes, it is. And my dog, Pipoca, is very happy on those days!"}]},"mistakes":[{"wrong":"I have 30 years.","options":["I'm 30 years old.","I have 30 years old.","I'm have 30."],"right":"I'm 30 years old.","why":"Para dizer a idade usamos o verbo be: I'm 30 (years old)."},{"wrong":"She is nurse.","options":["She's a nurse.","She's nurse.","She a nurse."],"right":"She's a nurse.","why":"Com profissão no singular usamos a / an: She's a nurse."},{"wrong":"He's a engineer.","options":["He's an engineer.","He's engineer.","He's a engineers."],"right":"He's an engineer.","why":"Antes de som de vogal usamos an: an engineer, an artist."},{"wrong":"He no is a teacher.","options":["He isn't a teacher.","He not is a teacher.","He don't is a teacher."],"right":"He isn't a teacher.","why":"Na negativa, not vem depois do be: he is not (isn't)."},{"wrong":"They is doctors.","options":["They are doctors.","They is doctor.","They are doctor."],"right":"They are doctors.","why":"Com they usamos are, e a profissão vai para o plural: doctors."},{"wrong":"Is she from Toronto? Yes, she's.","options":["Is she from Toronto? Yes, she is.","Is she from Toronto? Yes, is.","Is she from Toronto? Yes, is she."],"right":"Is she from Toronto? Yes, she is.","why":"Na resposta curta afirmativa não usamos a forma contraída: Yes, she is."}],"pron":{"focus":"Thirteen or thirty?","tip":"Listen to the stress. In thirteen, the strong part is at the end: thir-TEEN. In thirty, the strong part is at the start: THIR-ty. Listen and choose the number you hear.","type":"pairs","items":[{"a":"thirteen","b":"thirty"},{"a":"fourteen","b":"forty"},{"a":"fifteen","b":"fifty"},{"a":"sixteen","b":"sixty"},{"a":"seventeen","b":"seventy"},{"a":"eighteen","b":"eighty"},{"a":"nineteen","b":"ninety"}]},"practiceSentences":["Omar is a nurse in Toronto","What do you do","We aren't teachers","She isn't a student","How old is Jack","He is forty-one years old","Are they from Ireland","I'm not a doctor","Mei is twenty-six"],"readingTime":{"text":"Work around the world: three job profiles\nLars Berg is 45. He's from Norway, and he's a bus driver in Oslo. \"My job isn't easy in winter. It's dark at 3 pm! But the people on my bus are great.\"\nAmani Njoroge is 28. She's a vet in Nairobi, in Kenya. Her clinic is small, but it's busy. \"Animals are my life. Cats, dogs and sometimes a goat!\"\nTomás and Elena Ruiz are from Spain. They're 33 and 35. They aren't doctors or teachers. They're bakers in Seville. \"Our bakery is open at 7 am. Our bread is famous in the street!\"\nAnd you? What do you do? Are you happy at work?","questions":[{"prompt":"Who is a vet?","options":["Amani","Lars","Elena"],"correct":"Amani"},{"prompt":"Where is the bakery?","options":["in Seville","in Oslo","in Nairobi"],"correct":"in Seville"}]},"quiz":[{"prompt":"We ___ classmates.","options":["am","is","are"],"correct":"are","explain":"With we we use are."},{"prompt":"Jack ___ a nurse. He's a tour guide.","options":["isn't","aren't","am not"],"correct":"isn't","explain":"He / she + is not = isn't."},{"prompt":"___ they from Canada?","options":["Is","Are","Am"],"correct":"Are","explain":"Questions with they start with Are."},{"prompt":"Mei isn't ___ engineer. She works at a bank.","options":["a","an","is"],"correct":"an","explain":"Engineer starts with a vowel sound, so we say an."},{"prompt":"Omar is a nurse. He works in a…","options":["hospital","school","bakery"],"correct":"hospital","explain":"Nurses work in hospitals."},{"prompt":"You want to know someone's age. You say…","options":["How old are you?","How many years do you have?","What is your old?"],"correct":"How old are you?","explain":"For age, ask How old are you?"},{"prompt":"Your friend says: I'm a pilot! You say…","options":["Really? That's interesting!","Nice to meet you.","Oh no, I'm sorry."],"correct":"Really? That's interesting!","explain":"Show interest when someone tells you about their job."}],"writingPrompt":{"prompt":"Write about your job or your studies: what you do, where you work or study, and one thing you like about it.","help":["I'm a / an…","I work in / at…","My job is…","It isn't…, but…"],"words":40}},
  {"n":3,"module":1,"id":"syl-a1-03","title":"Family and things","emoji":"👨‍👩‍👧","description":"Talk about your family and your things, introduce someone and show things on camera","goals":["I can talk about my family with my, his, her, our and their.","I can use 's for family and things: Omar's daughter, Nina's dog.","I can use have / has and this, that, these and those.","I can introduce someone and show something on camera."],"grammarTip":"Use 's for people and their things: Jack's sons, Nina's dog. With he and she, have changes to has: I have a brother. She has a dog. Use this (one) and these (two or more) for things near you, and that and those for things far from you.","rules":[{"label":"I / you / we / they","form":"have","hint":"With I, you, we, they and two or more people.","examples":["I have one brother.","We have a small flat.","They have two cats."]},{"label":"he / she / it","form":"has","hint":"With he, she, it and one person.","examples":["Omar has a daughter.","Nina has a dog called Pipoca.","Jack has two teenage sons."]},{"label":"one thing (near)","form":"this","hint":"For one thing or person near you. Far: that.","examples":["This is my brother, Caio.","This photo is from Dublin.","Is this your phone?"]},{"label":"two or more (near)","form":"these","hint":"For two or more things near you. Far: those.","examples":["These are my keys.","These photos are from Taipei.","Are these your glasses?"]}],"words":[{"id":"mother","en":"mother","pt":"mãe","emoji":"👩"},{"id":"father","en":"father","pt":"pai","emoji":"👨"},{"id":"parents","en":"parents","pt":"pais (pai e mãe)","emoji":"👫"},{"id":"brother","en":"brother","pt":"irmão","emoji":"🧑"},{"id":"sister","en":"sister","pt":"irmã","emoji":"👩‍🦰"},{"id":"son","en":"son","pt":"filho","emoji":"👦"},{"id":"daughter","en":"daughter","pt":"filha","emoji":"👧"},{"id":"children","en":"children","pt":"filhos, crianças","emoji":"🧒"},{"id":"husband","en":"husband","pt":"marido","emoji":"🤵"},{"id":"wife","en":"wife","pt":"esposa","emoji":"👰"},{"id":"keys","en":"keys","pt":"chaves","emoji":"🔑"},{"id":"phone","en":"phone","pt":"celular","emoji":"📱"},{"id":"glasses","en":"glasses","pt":"óculos","emoji":"👓"},{"id":"wallet","en":"wallet","pt":"carteira","emoji":"👛"},{"id":"photo","en":"photo","pt":"foto","emoji":"🖼️"}],"chunks":[{"en":"This is my friend…","pt":"Este(a) é meu / minha amigo(a)…"},{"en":"Let me show you.","pt":"Deixa eu te mostrar."},{"en":"Can you see it?","pt":"Dá para ver?"},{"en":"These are my…","pt":"Estes(as) são meus / minhas…"},{"en":"Who's this?","pt":"Quem é esse(a)?"},{"en":"How old is he / she?","pt":"Quantos anos ele / ela tem?"}],"social":{"skill":"Introduce someone and show things on camera","tip":"To introduce a person, say This is my… and their name. To show something on camera, say Let me show you. Then check: Can you see it?","dialogue":[{"who":"Mei","line":"Jack, who's that in the photo behind you?"},{"who":"Jack","line":"Oh, ___","gap":"let me show you.","options":["let me show you.","see you later.","nice to meet you."]},{"who":"Jack","line":"Here. ___","gap":"Can you see it?","options":["Can you see it?","Can you spell it?","How old are you?"]},{"who":"Mei","line":"Yes! Who are these two boys?"},{"who":"Jack","line":"These are my sons, Sean and Liam. Sean is fifteen and Liam is thirteen."},{"who":"Mei","line":"They're very tall!"},{"who":"Jack","line":"Oh, and Liam is here now! Liam, come and say hi. ___","gap":"This is my friend Mei.","options":["This is my friend Mei.","These are my friends.","That is my phone."]},{"who":"Liam","line":"Hi, Mei. Nice to meet you."},{"who":"Mei","line":"Nice to meet you too, Liam!"}]},"mistakes":[{"wrong":"She have two children.","options":["She has two children.","She haves two children.","She is have two children."],"right":"She has two children.","why":"Com he / she usamos has, não have."},{"wrong":"The son of Jack is 15.","options":["Jack's son is 15.","Jack son is 15.","Jacks' son is 15."],"right":"Jack's son is 15.","why":"Para dizer de quem é usamos 's depois da pessoa: Jack's son."},{"wrong":"This are my keys.","options":["These are my keys.","This is my keys.","These is my keys."],"right":"These are my keys.","why":"Para duas ou mais coisas usamos these + are."},{"wrong":"Mei lives with his parents.","options":["Mei lives with her parents.","Mei lives with she parents.","Mei lives with hers parents."],"right":"Mei lives with her parents.","why":"O possessivo combina com quem possui: Mei é mulher, então her."},{"wrong":"Omar and Sara love his daughter.","options":["Omar and Sara love their daughter.","Omar and Sara love they daughter.","Omar and Sara love theirs daughter."],"right":"Omar and Sara love their daughter.","why":"Quando o dono é they (eles), o possessivo é their."},{"wrong":"I have three childs.","options":["I have three children.","I have three childrens.","I have three child."],"right":"I have three children.","why":"Child tem plural irregular: children, sem -s."}],"pron":{"focus":"Question intonation: up or down?","tip":"Yes / No questions usually go up at the end: Is this your phone? ↗ Questions with who, what, where or how old usually go down: Who's this? ↘ Listen and sort.","type":"sort","buckets":["Yes / No question ↗","Wh- question ↘"],"items":[{"text":"Is this your phone?","say":"Is this your phone?","bucket":"Yes / No question ↗"},{"text":"Are these your keys?","say":"Are these your keys?","bucket":"Yes / No question ↗"},{"text":"Is she your sister?","say":"Is she your sister?","bucket":"Yes / No question ↗"},{"text":"Are they your parents?","say":"Are they your parents?","bucket":"Yes / No question ↗"},{"text":"Is that your dog?","say":"Is that your dog?","bucket":"Yes / No question ↗"},{"text":"Who's this?","say":"Who's this?","bucket":"Wh- question ↘"},{"text":"How old is she?","say":"How old is she?","bucket":"Wh- question ↘"},{"text":"What's his name?","say":"What's his name?","bucket":"Wh- question ↘"},{"text":"Where are my glasses?","say":"Where are my glasses?","bucket":"Wh- question ↘"},{"text":"Who are these people?","say":"Who are these people?","bucket":"Wh- question ↘"}]},"practiceSentences":["This is my brother Caio","These are my keys","Omar has a daughter","Leila is Omar's daughter","Jack has two sons","Is that your phone","Those are her glasses","Mei lives with her parents","Their daughter is five"],"readingTime":{"text":"Family photos: posts from our class\nOmar, Toronto: This is my family on a Sunday in the park! This is my wife, Sara. She's a teacher. And this little girl is our daughter, Leila. She's five. These are her favourite toys, a red ball and a small bear.\nJack, Dublin: Me and my boys at a football match! Sean is fifteen and Liam is thirteen. They have my eyes and my love for football. They aren't good cooks. Like their dad!\nMei, Taipei: These are my mum and dad. I live with my parents. My dad has a small garden on our balcony. Can you see those plants? They're his babies!\nNina, Porto Alegre: And this is Pipoca, my dog. She has a big family online!","questions":[{"prompt":"Who is Leila?","options":["Omar's daughter","Omar's wife","Jack's daughter"],"correct":"Omar's daughter"},{"prompt":"Who has a garden on the balcony?","options":["Mei's dad","Mei's mum","Jack's son"],"correct":"Mei's dad"}]},"quiz":[{"prompt":"Nina ___ a dog.","options":["have","has","is"],"correct":"has","explain":"With he / she we use has."},{"prompt":"___ are my keys.","options":["This","These","That"],"correct":"These","explain":"Keys = two or more, so we use these."},{"prompt":"Omar and Sara have a daughter. ___ daughter is five.","options":["Their","His","Her"],"correct":"Their","explain":"For they, the possessive is their."},{"prompt":"Sean is ___ son.","options":["Jack","Jack's","Jacks"],"correct":"Jack's","explain":"Use 's for family: Jack's son."},{"prompt":"Your mother and your father are your…","options":["parents","children","sons"],"correct":"parents","explain":"Mother + father = parents."},{"prompt":"You want to show a photo on camera. You say…","options":["Let me show you. Can you see it?","Can you repeat that, please?","Where are you from?"],"correct":"Let me show you. Can you see it?","explain":"Say Let me show you, then check: Can you see it?"},{"prompt":"Your sister Clara is with you on a video call. You say…","options":["This is my sister, Clara.","These are my sister, Clara.","That are my sister, Clara."],"correct":"This is my sister, Clara.","explain":"One person: This is…"}],"writingPrompt":{"prompt":"Write a post for a photo of your family: who is in the photo, their names, ages and jobs.","help":["This is my…","My … is … years old.","He / She has…","These are my…"],"words":40}},
  {"n":4,"module":1,"id":"syl-a1-04","title":"Daily routine and time","emoji":"⏰","description":"Talk about your day, tell the time and agree with Me too and Me neither","goals":["I can talk about my daily routine.","I can use the present simple: I work, she works.","I can make negatives with don't and doesn't.","I can tell the time and agree: Me too / Me neither / It depends."],"grammarTip":"Use the present simple for things you do every day. With he, she and it, add -s to the verb: I work, she works. For the negative, use don't or doesn't + verb: I don't drink coffee. He doesn't work on Sundays. After doesn't, the verb has no -s.","rules":[{"label":"I / you / we / they","form":"work","hint":"No -s with I, you, we and they.","examples":["I work from home on Mondays.","We work in the same office.","They work at night."]},{"label":"he / she / it","form":"works","hint":"Add -s with he, she, it and one person.","examples":["Omar works at a hospital.","Mei works at a bank.","Jack works in Dublin."]},{"label":"negative: I / you / we / they","form":"don't","hint":"don't = do not + verb.","examples":["I don't eat breakfast.","We don't work on Sundays.","They don't get up early."]},{"label":"negative: he / she / it","form":"doesn't","hint":"doesn't = does not + verb with no -s.","examples":["Jack doesn't cook.","Nina doesn't get up late.","Mei doesn't drink coffee."]}],"words":[{"id":"getup","en":"get up","pt":"levantar(-se)","emoji":"🛏️"},{"id":"havebreakfast","en":"have breakfast","pt":"tomar café da manhã","emoji":"🥐"},{"id":"gotowork","en":"go to work","pt":"ir para o trabalho","emoji":"🚶"},{"id":"startwork","en":"start work","pt":"começar a trabalhar","emoji":"▶️"},{"id":"havelunch","en":"have lunch","pt":"almoçar","emoji":"🍝"},{"id":"finishwork","en":"finish work","pt":"terminar o trabalho","emoji":"🏁"},{"id":"gohome","en":"go home","pt":"ir para casa","emoji":"🏠"},{"id":"havedinner","en":"have dinner","pt":"jantar","emoji":"🍲"},{"id":"gotobed","en":"go to bed","pt":"ir dormir","emoji":"😴"},{"id":"everyday","en":"every day","pt":"todo dia","emoji":"📅"},{"id":"early","en":"early","pt":"cedo","emoji":"🌅"},{"id":"late","en":"late","pt":"tarde","emoji":"🌙"},{"id":"oclock","en":"o'clock","pt":"em ponto (horas)","emoji":"🕗"},{"id":"halfpast","en":"half past","pt":"e meia (horas)","emoji":"🕢"},{"id":"quarterpast","en":"quarter past","pt":"e quinze (horas)","emoji":"🕒"}],"chunks":[{"en":"What time do you get up?","pt":"A que horas você se levanta?"},{"en":"It's half past seven.","pt":"São sete e meia."},{"en":"Me too!","pt":"Eu também!"},{"en":"Me neither!","pt":"Eu também não!"},{"en":"It depends.","pt":"Depende."},{"en":"on Mondays / at the weekend","pt":"às segundas / no fim de semana"}],"social":{"skill":"Agree: Me too / Me neither / It depends","tip":"When you feel the same, say Me too! after a positive sentence (I love tea. Me too!). After a negative sentence, say Me neither! (I don't like Mondays. Me neither!). Not sure? Say It depends.","dialogue":[{"who":"Jack","line":"Morning, Nina! What time do you get up?"},{"who":"Nina","line":"At six o'clock. I'm a morning person. What about you?"},{"who":"Jack","line":"Six? Wow! I get up at half past nine. I'm a night owl."},{"who":"Nina","line":"So you start work late?"},{"who":"Jack","line":"___ Some days I start at ten, some days at two.","gap":"It depends.","options":["It depends.","Me neither.","Me too."]},{"who":"Nina","line":"I see. I don't like Mondays. I have a lot of meetings!"},{"who":"Jack","line":"___ Monday mornings are terrible.","gap":"Me neither!","options":["Me neither!","Me too!","It depends."]},{"who":"Nina","line":"But I love Saturdays. I play volleyball with my friends."},{"who":"Jack","line":"___ Saturday is football day for me!","gap":"Me too!","options":["Me too!","Me neither!","It depends."]}]},"mistakes":[{"wrong":"She work at a bank.","options":["She works at a bank.","She working at a bank.","She is work at a bank."],"right":"She works at a bank.","why":"Com he / she / it o verbo ganha -s: she works."},{"wrong":"He don't like coffee.","options":["He doesn't like coffee.","He doesn't likes coffee.","He not like coffee."],"right":"He doesn't like coffee.","why":"Com he / she / it a negativa é doesn't, não don't."},{"wrong":"Jack doesn't cooks.","options":["Jack doesn't cook.","Jack don't cooks.","Jack not cooks."],"right":"Jack doesn't cook.","why":"Depois de doesn't o verbo fica sem -s."},{"wrong":"Is half past seven.","options":["It's half past seven.","Are half past seven.","Is seven and half."],"right":"It's half past seven.","why":"Para dizer as horas o inglês precisa do sujeito it: It's…"},{"wrong":"I go to the work at 8.","options":["I go to work at 8.","I go in the work at 8.","I go to the work in 8."],"right":"I go to work at 8.","why":"Go to work é uma expressão fixa, sem the; para horas usamos at."},{"wrong":"A: I don't drink coffee. B: Me too.","options":["A: I don't drink coffee. B: Me neither.","A: I don't drink coffee. B: Me also.","A: I don't drink coffee. B: Me no."],"right":"A: I don't drink coffee. B: Me neither.","why":"Para concordar com uma frase negativa usamos Me neither."}],"pron":{"focus":"The -s ending: three sounds","tip":"The -s on a verb has three sounds. /s/ after sounds like k, t, p: works. /z/ after most other sounds: plays. /ɪz/ (an extra syllable) after s, sh, ch, x: watches. Listen and sort.","type":"sort","buckets":["/s/ works","/z/ plays","/ɪz/ watches"],"items":[{"text":"works","say":"works","bucket":"/s/ works"},{"text":"gets","say":"gets","bucket":"/s/ works"},{"text":"eats","say":"eats","bucket":"/s/ works"},{"text":"walks","say":"walks","bucket":"/s/ works"},{"text":"plays","say":"plays","bucket":"/z/ plays"},{"text":"goes","say":"goes","bucket":"/z/ plays"},{"text":"reads","say":"reads","bucket":"/z/ plays"},{"text":"lives","say":"lives","bucket":"/z/ plays"},{"text":"watches","say":"watches","bucket":"/ɪz/ watches"},{"text":"finishes","say":"finishes","bucket":"/ɪz/ watches"},{"text":"washes","say":"washes","bucket":"/ɪz/ watches"},{"text":"relaxes","say":"relaxes","bucket":"/ɪz/ watches"}]},"practiceSentences":["I get up at seven o'clock","Omar works at night","Mei doesn't drink coffee","We don't work on Sundays","Jack goes to bed late","She has lunch at one","I don't eat breakfast","Nina walks her dog every morning","It's half past nine"],"readingTime":{"text":"A day in my life: Sofía, a baker in Buenos Aires\nMy day starts very early. I get up at half past three. I don't have breakfast at home. I just drink a glass of water.\nI start work at four o'clock. I make bread, cakes and medialunas, the small croissants of Argentina.\nThe shop opens at eight o'clock. My husband, Martín, works in the shop. He doesn't make bread, but he talks to the customers all day. He loves that!\nI finish work at one o'clock and have lunch with Martín. In the afternoon, I sleep for two hours.\nIn the evening, I read or watch TV. I go to bed at nine. My friends say, \"Sofía, you're like a grandmother!\" But I love my job.","questions":[{"prompt":"When does Sofía start work?","options":["at four o'clock","at half past three","at eight o'clock"],"correct":"at four o'clock"},{"prompt":"What does Martín do in the shop?","options":["He talks to the customers.","He makes bread.","He sleeps."],"correct":"He talks to the customers."}]},"quiz":[{"prompt":"Mei ___ at a bank.","options":["work","works","working"],"correct":"works","explain":"With he / she, add -s: she works."},{"prompt":"I ___ drink coffee.","options":["don't","doesn't","not"],"correct":"don't","explain":"With I, the negative is don't."},{"prompt":"Jack doesn't ___ breakfast.","options":["eat","eats","eating"],"correct":"eat","explain":"After doesn't, the verb has no -s."},{"prompt":"Omar sometimes works ___ night.","options":["at","in","on"],"correct":"at","explain":"We say at night."},{"prompt":"7:30. It's…","options":["half past seven","seven past half","half to seven"],"correct":"half past seven","explain":"30 minutes after the hour = half past."},{"prompt":"8:15. It's…","options":["quarter past eight","quarter to eight","eight and quarter"],"correct":"quarter past eight","explain":"15 minutes after the hour = quarter past."},{"prompt":"Your friend says: I don't like Mondays. You feel the same. You say…","options":["Me neither!","Me too!","It depends."],"correct":"Me neither!","explain":"After a negative sentence, agree with Me neither."},{"prompt":"Your friend says: I love weekends! You love them too. You say…","options":["Me too!","Me neither!","Nice to meet you."],"correct":"Me too!","explain":"After a positive sentence, agree with Me too."}],"writingPrompt":{"prompt":"Write about a normal day for you: when you get up, work or study, eat and go to bed.","help":["I get up at…","I start work / class at…","I don't…","In the evening, I…"],"words":50}},
  {"n":5,"module":2,"id":"syl-a1-05","title":"Questions with do and does","emoji":"❓","description":"Ask and answer questions about people's lives with do and does, and keep a conversation going","goals":["I can ask questions with do and does.","I can give short answers: Yes, I do. No, she doesn't.","I can ask Why? and answer with Because…","I can keep a conversation going and ask what a word means."],"grammarTip":"In the present simple, questions need do or does. Use do with I, you, we and they. Use does with he, she and it, and the main verb has no -s: Does she work? For short answers, repeat do or does: Yes, I do. No, he doesn't.","rules":[{"label":"I / you / we / they","form":"do","hint":"Question: (Wh-) + do + person + verb.","examples":["Do you work from home?","Where do you live?","What do they do at the weekend?"]},{"label":"he / she / it","form":"does","hint":"Does + person + verb, with no -s on the verb.","examples":["Does Mei play the piano?","Where does Omar work?","What time does Jack get up?"]},{"label":"Short answer: no","form":"doesn't","hint":"No, he / she doesn't. With I, you, we, they: No, I don't.","examples":["Does Jack cook? No, he doesn't.","Does Nina have a cat? No, she doesn't.","Jack doesn't cook at home."]},{"label":"Why? – Because…","form":"because","hint":"Answer a Why question with because.","examples":["I study English because I want to travel.","Nina likes Mondays because she works from home.","Why tea? Because I love it."]}],"words":[{"id":"getup","en":"get up","pt":"levantar-se","emoji":"⏰"},{"id":"havebreakfast","en":"have breakfast","pt":"tomar café da manhã","emoji":"🥐"},{"id":"gotowork","en":"go to work","pt":"ir trabalhar","emoji":"💼"},{"id":"takethebus","en":"take the bus","pt":"pegar o ônibus","emoji":"🚌"},{"id":"watchtv","en":"watch TV","pt":"assistir TV","emoji":"📺"},{"id":"listentomusic","en":"listen to music","pt":"ouvir música","emoji":"🎧"},{"id":"readthenews","en":"read the news","pt":"ler as notícias","emoji":"📰"},{"id":"drinkcoffee","en":"drink coffee","pt":"tomar café","emoji":"☕"},{"id":"playgames","en":"play games","pt":"jogar (jogos)","emoji":"🎮"},{"id":"dohomework","en":"do homework","pt":"fazer lição de casa","emoji":"📝"},{"id":"why","en":"why","pt":"por quê","emoji":"🤔"},{"id":"because","en":"because","pt":"porque","emoji":"💡"},{"id":"question","en":"question","pt":"pergunta","emoji":"❓"},{"id":"answer","en":"answer","pt":"resposta","emoji":"💬"},{"id":"interview","en":"interview","pt":"entrevista","emoji":"🎤"}],"chunks":[{"en":"What about you?","pt":"E você?"},{"en":"What do you do?","pt":"O que você faz? (trabalho)"},{"en":"Sorry, what does … mean?","pt":"Desculpa, o que significa …?"},{"en":"What do you mean?","pt":"Como assim?"},{"en":"Why? – Because…","pt":"Por quê? – Porque…"},{"en":"Yes, I do. / No, I don't.","pt":"Sim. / Não. (resposta curta)"}],"social":{"skill":"Keep the conversation going and ask what something means","tip":"Don't just answer: ask a question back, like What about you? or Do you like it? If you don't know a word, say Sorry, what does … mean?","dialogue":[{"who":"Nina","line":"So, Omar, what do you do in your free time?"},{"who":"Omar","line":"I cook a lot. I love Jordanian food. ___","gap":"What about you?","options":["What about you?","How old are you?","Where is it?"]},{"who":"Nina","line":"I play volleyball on Saturdays. Do you play a sport?"},{"who":"Omar","line":"No, I don't. Some weeks I work night shifts, so I sleep a lot!"},{"who":"Nina","line":"Sorry, ___","gap":"what does 'night shift' mean?","options":["what does 'night shift' mean?","what time is it?","where do you live?"]},{"who":"Omar","line":"I work at night, from 7 pm to 7 am, at the hospital."},{"who":"Nina","line":"Oh, I see! ___","gap":"Do you like it?","options":["Do you like it?","Do you have a pen?","Is it your dog?"]},{"who":"Omar","line":"Not really. I'm always tired! But my colleagues are great."},{"who":"Nina","line":"That's important. Good colleagues make a big difference."}]},"mistakes":[{"wrong":"You like coffee?","options":["Do you like coffee?","Are you like coffee?","Does you like coffee?"],"right":"Do you like coffee?","why":"Perguntas no present simple precisam de do/does antes da pessoa."},{"wrong":"Where she works?","options":["Where does she work?","Where does she works?","Where do she work?"],"right":"Where does she work?","why":"Com she usamos does, e o verbo principal fica sem -s."},{"wrong":"Does he lives in Toronto?","options":["Does he live in Toronto?","Do he live in Toronto?","Does he living in Toronto?"],"right":"Does he live in Toronto?","why":"O -s já está em does; o verbo principal volta à forma base."},{"wrong":"Do you like tea? – Yes, I like.","options":["Do you like tea? – Yes, I do.","Do you like tea? – Yes, I am.","Do you like tea? – Yes, I does."],"right":"Do you like tea? – Yes, I do.","why":"Na resposta curta, repetimos do/does: Yes, I do."},{"wrong":"Why you study English?","options":["Why do you study English?","Why you do study English?","Why are you study English?"],"right":"Why do you study English?","why":"Depois de Why também precisamos de do/does antes da pessoa."},{"wrong":"What means 'shift'?","options":["What does 'shift' mean?","What does 'shift' means?","What is mean 'shift'?"],"right":"What does 'shift' mean?","why":"Para perguntar o significado: What does … mean? (mean sem -s)."}],"pron":{"focus":"Two th sounds: think and this","tip":"Put your tongue between your teeth. In think, there is only air. In this, your voice is on too. Listen and choose the sound.","type":"sort","buckets":["th as in think","th as in this"],"items":[{"text":"think","say":"think","bucket":"th as in think"},{"text":"three","say":"three","bucket":"th as in think"},{"text":"thank you","say":"thank you","bucket":"th as in think"},{"text":"Thursday","say":"Thursday","bucket":"th as in think"},{"text":"birthday","say":"birthday","bucket":"th as in think"},{"text":"month","say":"month","bucket":"th as in think"},{"text":"this","say":"this","bucket":"th as in this"},{"text":"the","say":"the","bucket":"th as in this"},{"text":"they","say":"they","bucket":"th as in this"},{"text":"mother","say":"mother","bucket":"th as in this"},{"text":"father","say":"father","bucket":"th as in this"},{"text":"brother","say":"brother","bucket":"th as in this"}]},"practiceSentences":["Do you work from home","Where does Omar work","What time do you get up","Does Mei play the piano","Yes, she does","No, I don't","Why do you study English","Because I want a better job","What does this word mean"],"readingTime":{"text":"Five minutes with Femi, a London taxi driver\nWhere do you work, Femi?\nI drive a black taxi in London, from Monday to Friday. I know all the streets in the city!\nWhat time do you start?\nI start at 6 am. I get up at 5 and I have a big breakfast. Tea, eggs and toast.\nDo you like your job?\nYes, I do! I meet people from all over the world every day. I ask them questions, and they ask me questions too.\nWhat do you do after work?\nI play football with friends, I listen to music and I go to bed early. My son studies music, so our home is never quiet!","questions":[{"prompt":"What time does Femi get up?","options":["At 5 am","At 6 am","At 7 am"],"correct":"At 5 am"},{"prompt":"Who studies music?","options":["Femi's son","Femi","Femi's friends"],"correct":"Femi's son"}]},"quiz":[{"prompt":"___ you work from home?","options":["Do","Does","Are"],"correct":"Do","explain":"With you we use do."},{"prompt":"Where ___ Mei live?","options":["do","does","is"],"correct":"does","explain":"With he / she (Mei) we use does."},{"prompt":"Does Jack like football? – Yes, he ___.","options":["does","do","is"],"correct":"does","explain":"Short answer: repeat does."},{"prompt":"What ___ Omar do? – He's a nurse.","options":["does","do","is"],"correct":"does","explain":"What does he do? asks about a job."},{"prompt":"Why do you study English? – ___ I want a new job.","options":["Because","Why","What"],"correct":"Because","explain":"We answer Why with because."},{"prompt":"You don't understand a word. You say…","options":["Sorry, what does 'shift' mean?","What about you?","Nice to meet you."],"correct":"Sorry, what does 'shift' mean?","explain":"Ask what a word means with What does … mean?"},{"prompt":"You answer a question and want to ask the same question. You say…","options":["What about you?","Can you repeat that?","Goodbye."],"correct":"What about you?","explain":"What about you? sends the question back."}],"writingPrompt":{"prompt":"Write five questions for an interview with a new classmate. Ask about work, routine and free time.","help":["Where do you…?","What time do you…?","Do you like…?","Why do you…?"],"words":40}},
  {"n":6,"module":2,"id":"syl-a1-06","title":"Free time and hobbies","emoji":"🎨","description":"Talk about hobbies and how often you do things, and invite a friend or say no nicely","goals":["I can talk about my hobbies with like, love and hate + -ing.","I can say how often I do things: always, usually, sometimes, never.","I can ask How often do you…? and answer once or twice a week.","I can invite a friend, say yes, and say no in a nice way."],"grammarTip":"Frequency words go before the main verb: I usually play tennis. With be, they go after: She is always late. After like, love and hate, use the verb with -ing: I love cooking. To ask, say How often do you…?","rules":[{"label":"100%","form":"always","hint":"Before the main verb, but after be.","examples":["Nina always gets up early.","Omar always drinks tea after dinner.","Jack is always late."]},{"label":"about 50%","form":"sometimes","hint":"Before the main verb, but after be.","examples":["I sometimes go hiking.","Mei sometimes plays the piano at night.","We are sometimes tired on Mondays."]},{"label":"0%","form":"never","hint":"Never is already negative: no don't.","examples":["Jack never cooks.","I never watch TV in the morning.","She is never bored."]},{"label":"like + -ing","form":"like","hint":"Like, love and hate + verb with -ing.","examples":["I like reading.","Do you like dancing?","Mei doesn't like running."]}],"words":[{"id":"hobby","en":"hobby","pt":"hobby, passatempo","emoji":"🎯"},{"id":"freetime","en":"free time","pt":"tempo livre","emoji":"🕰️"},{"id":"weekend","en":"weekend","pt":"fim de semana","emoji":"📅"},{"id":"reading","en":"reading","pt":"ler, leitura","emoji":"📚"},{"id":"cooking","en":"cooking","pt":"cozinhar","emoji":"🍳"},{"id":"hiking","en":"hiking","pt":"fazer trilha","emoji":"🥾"},{"id":"dancing","en":"dancing","pt":"dançar","emoji":"💃"},{"id":"swimming","en":"swimming","pt":"nadar","emoji":"🏊"},{"id":"painting","en":"painting","pt":"pintar","emoji":"🎨"},{"id":"videogames","en":"playing video games","pt":"jogar videogame","emoji":"🎮"},{"id":"guitar","en":"playing the guitar","pt":"tocar violão / guitarra","emoji":"🎸"},{"id":"gym","en":"going to the gym","pt":"ir à academia","emoji":"🏋️"},{"id":"howoften","en":"how often","pt":"com que frequência","emoji":"🔄"},{"id":"onceaweek","en":"once a week","pt":"uma vez por semana","emoji":"1️⃣"},{"id":"twiceaweek","en":"twice a week","pt":"duas vezes por semana","emoji":"2️⃣"}],"chunks":[{"en":"How often do you…?","pt":"Com que frequência você…?"},{"en":"Do you want to … on Saturday?","pt":"Quer … no sábado?"},{"en":"Sounds fun!","pt":"Parece divertido! / Boa!"},{"en":"I'd love to, but I can't.","pt":"Eu adoraria, mas não posso."},{"en":"Maybe next time!","pt":"Fica para a próxima!"},{"en":"once / twice a week","pt":"uma / duas vezes por semana"}],"social":{"skill":"Invite someone, accept, and say no nicely","tip":"To invite, say Do you want to…? To say yes: Sounds fun! To say no, be kind: I'd love to, but I can't. Then give a reason, or say Maybe next time!","dialogue":[{"who":"Kevin","line":"Mei, do you like hiking?"},{"who":"Mei","line":"Yes, I love it! I go hiking about twice a month."},{"who":"Kevin","line":"Great! Do you want to go to Elephant Mountain on Saturday?"},{"who":"Mei","line":"___ What time?","gap":"Sounds fun!","options":["Sounds fun!","Never mind.","I'm sorry."]},{"who":"Kevin","line":"At 8 am. And on Sunday there's karaoke with our team. Do you want to come?"},{"who":"Mei","line":"Oh, ___ I always have my piano class on Sunday evenings.","gap":"I'd love to, but I can't.","options":["I'd love to, but I can't.","yes, I'm fine.","me neither."]},{"who":"Kevin","line":"No problem! ___","gap":"Maybe next time!","options":["Maybe next time!","See you on Sunday!","Me too!"]},{"who":"Mei","line":"Yes, next time! See you on Saturday. I can bring the bubble tea!"}]},"mistakes":[{"wrong":"I like read.","options":["I like reading.","I like to reading.","I like reads."],"right":"I like reading.","why":"Depois de like, love e hate, usamos o verbo com -ing."},{"wrong":"I go always to the gym.","options":["I always go to the gym.","I go to always the gym.","Always I go the gym."],"right":"I always go to the gym.","why":"O advérbio de frequência vem antes do verbo principal."},{"wrong":"She always is late.","options":["She is always late.","She always are late.","She always late."],"right":"She is always late.","why":"Com o verbo be, o advérbio vem depois: is always."},{"wrong":"I never don't watch TV.","options":["I never watch TV.","I don't never watch TV.","I not never watch TV."],"right":"I never watch TV.","why":"Never já é negativo; não use don't junto."},{"wrong":"Do you want go to the cinema?","options":["Do you want to go to the cinema?","Do you want going to the cinema?","Do you want go the cinema?"],"right":"Do you want to go to the cinema?","why":"Depois de want, usamos to + verbo."},{"wrong":"I go to the gym two times for week.","options":["I go to the gym twice a week.","I go to the gym twice for week.","I go to the gym two for week."],"right":"I go to the gym twice a week.","why":"Em inglês dizemos once a week, twice a week (não for week)."}],"pron":{"focus":"th, t or f? (three / tree / free)","tip":"For th, put your tongue between your teeth and push air out. For t, your tongue stays behind your teeth. For f, your top teeth touch your lip. Listen and choose the word.","type":"pairs","items":[{"a":"three","b":"tree"},{"a":"thank","b":"tank"},{"a":"thin","b":"tin"},{"a":"thought","b":"taught"},{"a":"both","b":"boat"},{"a":"theme","b":"team"},{"a":"three","b":"free"}]},"practiceSentences":["I usually go hiking on Sundays","How often do you play volleyball","Jack never cooks at home","Mei likes playing the piano","Omar loves cooking for his family","She is always happy on Saturdays","Do you want to come","That sounds fun","I'd love to, but I can't","We sometimes watch films at the weekend"],"readingTime":{"text":"What makes a happy weekend?\nWe ask four readers from around the world: what do you usually do at the weekend?\nIngrid, 34, Oslo, Norway: In winter, I often go skiing with my kids. We always take hot chocolate with us. It's cold, but we love it!\nKenji, 52, Osaka, Japan: I'm a cook, so I usually work on Saturdays. On Sundays, I never cook! My wife and I go to a small restaurant near our home.\nValentina, 23, Buenos Aires, Argentina: I like sleeping late. On Sunday afternoon, my family has a big lunch together. My dad always makes the meat.\nSam, 19, Sydney, Australia: I go surfing every Saturday morning. In the evening, I sometimes play video games online with friends.\nSo, what's the secret? Time with people we love, and time for things we like doing.","questions":[{"prompt":"Who never cooks on Sundays?","options":["Kenji","Ingrid","Sam"],"correct":"Kenji"},{"prompt":"How often does Sam go surfing?","options":["Every Saturday","Never","Once a month"],"correct":"Every Saturday"}]},"quiz":[{"prompt":"Jack ___ cooks. He's a terrible cook!","options":["never","always","usually"],"correct":"never","explain":"A terrible cook doesn't cook: never = 0%."},{"prompt":"Do you like ___?","options":["dancing","dance","dances"],"correct":"dancing","explain":"Like + verb with -ing."},{"prompt":"She ___ late.","options":["is always","always is","always"],"correct":"is always","explain":"With be, the frequency word goes after it."},{"prompt":"___ do you go to the gym? – Twice a week.","options":["How often","How many","What time"],"correct":"How often","explain":"How often asks about frequency."},{"prompt":"Mei plays the piano every day. She ___ plays the piano.","options":["always","never","sometimes"],"correct":"always","explain":"Every day = always."},{"prompt":"A friend invites you, and you want to go. You say…","options":["Sounds fun!","Maybe next time.","I'm busy."],"correct":"Sounds fun!","explain":"Sounds fun! is a happy yes."},{"prompt":"A friend invites you, but you can't go. You say…","options":["I'd love to, but I can't.","Yes, I'd love to!","Me too."],"correct":"I'd love to, but I can't.","explain":"This is a kind way to say no."}],"writingPrompt":{"prompt":"Write about your weekend: what you usually do, how often you do it, and what you like doing.","help":["On Saturdays, I usually…","I sometimes…","I never…","I really like …ing because…"],"words":50}},
  {"n":7,"module":2,"id":"syl-a1-07","title":"My home and neighbourhood","emoji":"🏘️","description":"Describe your home and neighbourhood with there is / there are, and ask for and give directions","goals":["I can describe my home with there is and there are.","I can ask Is there…? and Are there…? about a place.","I can say where things are: next to, opposite, near.","I can ask for directions and give simple directions."],"grammarTip":"Use there is for one thing and there are for two or more: There is a park. There are two cafés. For questions, change the order: Is there a bank near here? Are there any shops? Negative: there isn't, there aren't. To say where: next to, opposite, near, in, on.","rules":[{"label":"one thing","form":"there is","hint":"Short form: there's.","examples":["There is a park near my flat.","There is a sofa in the living room.","In my street there is a small café."]},{"label":"two or more","form":"there are","hint":"Negative: there aren't.","examples":["There are two bedrooms in my flat.","There are a lot of shops in my town.","There are some plants next to the window."]},{"label":"question: one","form":"Is there","hint":"Answer: Yes, there is. / No, there isn't.","examples":["Is there a bank near here?","Is there a garden? Yes, there is.","Is there a bus stop opposite the school?"]},{"label":"question: two or more","form":"Are there","hint":"Use any in questions. Answer: Yes, there are. / No, there aren't.","examples":["Are there any good restaurants here?","Are there two bathrooms?","Are there any buses to the airport?"]}],"words":[{"id":"house","en":"house","pt":"casa","emoji":"🏠"},{"id":"flat","en":"flat / apartment","pt":"apartamento","emoji":"🏢"},{"id":"bedroom","en":"bedroom","pt":"quarto","emoji":"🛏️"},{"id":"kitchen","en":"kitchen","pt":"cozinha","emoji":"🍳"},{"id":"bathroom","en":"bathroom","pt":"banheiro","emoji":"🛁"},{"id":"livingroom","en":"living room","pt":"sala de estar","emoji":"🛋️"},{"id":"garden","en":"garden","pt":"jardim, quintal","emoji":"🌷"},{"id":"supermarket","en":"supermarket","pt":"supermercado","emoji":"🛒"},{"id":"pharmacy","en":"pharmacy","pt":"farmácia","emoji":"💊"},{"id":"busstop","en":"bus stop","pt":"ponto de ônibus","emoji":"🚏"},{"id":"park","en":"park","pt":"parque","emoji":"🌳"},{"id":"station","en":"train station","pt":"estação de trem","emoji":"🚉"},{"id":"nextto","en":"next to","pt":"ao lado de","emoji":"↔️"},{"id":"opposite","en":"opposite","pt":"em frente a (do outro lado)","emoji":"🔄"},{"id":"turnleft","en":"turn left","pt":"vire à esquerda","emoji":"⬅️"}],"chunks":[{"en":"Excuse me, how do I get to…?","pt":"Com licença, como eu chego a…?"},{"en":"Is there a … near here?","pt":"Tem um(a) … aqui perto?"},{"en":"Go straight on.","pt":"Siga em frente."},{"en":"Turn left / right.","pt":"Vire à esquerda / direita."},{"en":"It's next to / opposite the…","pt":"Fica ao lado de / em frente ao…"},{"en":"It's about five minutes' walk.","pt":"Fica a uns cinco minutos a pé."}],"social":{"skill":"Ask for and give directions","tip":"Start with Excuse me, then ask How do I get to…? or Is there a … near here? To help someone, use short sentences: Go straight on. Turn left. It's next to the…","dialogue":[{"who":"Visitor","line":"Hi! Excuse me, ___ St Stephen's Green?","gap":"how do I get to","options":["how do I get to","what do you think of","how often do you go to"]},{"who":"Jack","line":"Sure! Go straight on and turn left into Grafton Street. Walk to the end of the street, and the park is there."},{"who":"Visitor","line":"Is it far?"},{"who":"Jack","line":"No, it's about ten minutes' walk."},{"who":"Visitor","line":"Great. And ___","gap":"is there a pharmacy near here?","options":["is there a pharmacy near here?","are you a pharmacist?","where are you from?"]},{"who":"Jack","line":"Yes, there is. It's next to the bank, on the right."},{"who":"Visitor","line":"___","gap":"Thanks a lot!","options":["Thanks a lot!","You're welcome!","Nice to meet you!"]},{"who":"Jack","line":"You're welcome. Enjoy Dublin!"}]},"mistakes":[{"wrong":"Have a bank near here?","options":["Is there a bank near here?","There is a bank near here?","Has a bank near here?"],"right":"Is there a bank near here?","why":"Para perguntar se algo existe, use Is there…? (não Have/Has)."},{"wrong":"In my street have two cafés.","options":["In my street there are two cafés.","In my street there is two cafés.","In my street has two cafés."],"right":"In my street there are two cafés.","why":"Para dizer que algo existe num lugar, use there is / there are, não have."},{"wrong":"There is three bedrooms.","options":["There are three bedrooms.","There have three bedrooms.","They are three bedrooms."],"right":"There are three bedrooms.","why":"Com plural usamos there are."},{"wrong":"The café is next the bank.","options":["The café is next to the bank.","The café is next of the bank.","The café is next at the bank."],"right":"The café is next to the bank.","why":"Next sempre vem com to: next to."},{"wrong":"I live in the fifth floor.","options":["I live on the fifth floor.","I live at the fifth floor.","I live in fifth floor."],"right":"I live on the fifth floor.","why":"Para andar de prédio usamos on: on the fifth floor."},{"wrong":"How I go to the station?","options":["How do I get to the station?","How I get to the station?","How get I to the station?"],"right":"How do I get to the station?","why":"A pergunta com How precisa de do: How do I get to…?"}],"pron":{"focus":"th in places: north and there","tip":"Both sounds start with your tongue between your teeth. In north, there is only air. In there, your voice is on too. Listen and choose the sound.","type":"sort","buckets":["th as in north","th as in there"],"items":[{"text":"north","say":"north","bucket":"th as in north"},{"text":"south","say":"south","bucket":"th as in north"},{"text":"bath","say":"bath","bucket":"th as in north"},{"text":"theatre","say":"theatre","bucket":"th as in north"},{"text":"thirty","say":"thirty","bucket":"th as in north"},{"text":"path","say":"path","bucket":"th as in north"},{"text":"there","say":"there","bucket":"th as in there"},{"text":"these","say":"these","bucket":"th as in there"},{"text":"that","say":"that","bucket":"th as in there"},{"text":"other","say":"other","bucket":"th as in there"},{"text":"together","say":"together","bucket":"th as in there"},{"text":"the","say":"the","bucket":"th as in there"}]},"practiceSentences":["There is a park near my flat","There are two bedrooms","Is there a bank near here","Are there any shops in your street","There isn't a garden","The pharmacy is next to the bank","How do I get to the station","Go straight on and turn left","My flat is on the third floor"],"readingTime":{"text":"Neighbourhood guide: Da'an, Taipei\nHi! I'm Mei, and I live with my parents in Da'an. It's a quiet area in the centre of Taipei.\nThere's a big green park here, Daan Forest Park. I go there on Sunday mornings. There are a lot of trees, birds and people with dogs.\nThere are lots of small cafés in my street. My favourite café is next to a bookshop. And of course, there are bubble tea shops on every corner!\nIs there a night market? Yes, there is: Shida Night Market, near the university. It's great for cheap food.\nGetting around is easy. There's an MRT (metro) station next to the park, and there are buses everywhere.\nIs there a problem? Well, there aren't many big supermarkets. But there are a lot of small 24-hour shops.","questions":[{"prompt":"Where is Mei's favourite café?","options":["Next to a bookshop","Opposite the park","At the night market"],"correct":"Next to a bookshop"},{"prompt":"What is a problem in Da'an?","options":["There aren't many big supermarkets.","There aren't any cafés.","There isn't a park."],"correct":"There aren't many big supermarkets."}]},"quiz":[{"prompt":"___ a big park in my town.","options":["There is","There are","It has"],"correct":"There is","explain":"One park: there is."},{"prompt":"___ two bathrooms in the flat.","options":["There are","There is","Have"],"correct":"There are","explain":"Two bathrooms (plural): there are."},{"prompt":"___ a supermarket near here?","options":["Is there","Are there","Has"],"correct":"Is there","explain":"Question about one thing: Is there…?"},{"prompt":"The bank and the pharmacy are side by side. The bank is ___ the pharmacy.","options":["next to","opposite","far from"],"correct":"next to","explain":"Side by side = next to."},{"prompt":"My flat is ___ the fourth floor.","options":["on","in","at"],"correct":"on","explain":"We say on the … floor."},{"prompt":"You are lost in a new city. You say…","options":["Excuse me, how do I get to the station?","Excuse me, where are you from?","Excuse me, what do you do?"],"correct":"Excuse me, how do I get to the station?","explain":"Ask for directions with How do I get to…?"},{"prompt":"Someone asks for directions. The place is near. You say…","options":["It's about five minutes' walk.","Sounds fun!","I'd love to."],"correct":"It's about five minutes' walk.","explain":"This tells the person it is near."}],"writingPrompt":{"prompt":"Write a short guide to your neighbourhood for a visitor: what there is, where things are, and your favourite place.","help":["I live in…","There is a … near my home.","There are a lot of…","My favourite place is … It's next to…"],"words":50}},
  {"n":8,"module":2,"id":"syl-a1-08","title":"Review 1: Modules 1–2","emoji":"🔁","description":"Review be and the present simple, there is / are, frequency words and questions, and write a profile for the class magazine","goals":["I can choose between be and do / does.","I can ask and answer questions about people's lives.","I can say Let me think… or How do you say…? when I need time or a word.","I can write a short profile of a classmate for a class magazine."],"grammarTip":"Use be (am, is, are) with names, ages, jobs, places and feelings: She is a nurse. I'm tired. For other verbs, use the present simple: She works at a hospital. Questions with be: Is he Irish? Questions with other verbs need do or does: Does he cook?","rules":[{"label":"be: he / she / it","form":"is","hint":"Be for name, age, job, place, feelings. Question: Is…?","examples":["Omar is a nurse.","Is Mei shy?","Jack is 41."]},{"label":"be: you / we / they","form":"are","hint":"Question: Are you…?","examples":["Where are you from?","We are classmates.","Are you tired today?"]},{"label":"other verbs: he / she / it","form":"does","hint":"Does + person + verb (no -s).","examples":["Does Nina work from home?","Where does Omar live?","What time does Jack get up?"]},{"label":"other verbs: I / you / we / they","form":"do","hint":"Do + person + verb.","examples":["Do you like tea?","Where do your parents live?","What do you do?"]}],"words":[{"id":"nurse","en":"nurse","pt":"enfermeiro(a)","emoji":"🩺"},{"id":"teacher","en":"teacher","pt":"professor(a)","emoji":"👩‍🏫"},{"id":"daughter","en":"daughter","pt":"filha","emoji":"👧"},{"id":"brother","en":"brother","pt":"irmão","emoji":"👦"},{"id":"getup","en":"get up","pt":"levantar-se","emoji":"⏰"},{"id":"workfromhome","en":"work from home","pt":"trabalhar de casa","emoji":"💻"},{"id":"nightshift","en":"night shift","pt":"plantão noturno","emoji":"🌙"},{"id":"freetime","en":"free time","pt":"tempo livre","emoji":"🕰️"},{"id":"hiking","en":"hiking","pt":"fazer trilha","emoji":"🥾"},{"id":"cooking","en":"cooking","pt":"cozinhar","emoji":"🍳"},{"id":"flat","en":"flat","pt":"apartamento","emoji":"🏢"},{"id":"nextto","en":"next to","pt":"ao lado de","emoji":"↔️"},{"id":"usually","en":"usually","pt":"geralmente","emoji":"🔄"},{"id":"magazine","en":"magazine","pt":"revista","emoji":"📰"},{"id":"profile","en":"profile","pt":"perfil","emoji":"🪪"}],"chunks":[{"en":"Let me think…","pt":"Deixa eu pensar…"},{"en":"Hmm, good question!","pt":"Hmm, boa pergunta!"},{"en":"What's the word?","pt":"Qual é a palavra?"},{"en":"How do you say … in English?","pt":"Como se diz … em inglês?"},{"en":"What do you call…?","pt":"Como se chama…?"},{"en":"It's a kind of…","pt":"É um tipo de…"}],"social":{"skill":"Buy time and ask for a word","tip":"It's OK to stop and think. Say Let me think… or Good question! If you don't know a word, ask What's the word? or explain it: What do you call the place with…?","dialogue":[{"who":"Teacher Ana","line":"Nina, this is for the class magazine. What do you usually do on Saturdays?"},{"who":"Nina","line":"___ I usually play volleyball with friends. Then I walk my dog, Pipoca.","gap":"Let me think…","options":["Let me think…","Nice to meet you.","Turn left."]},{"who":"Teacher Ana","line":"Oh, nice! What's Pipoca like?"},{"who":"Nina","line":"He's very… ___ He loves games and he never stops!","gap":"What's the word?","options":["What's the word?","What about you?","Is there a park?"]},{"who":"Teacher Ana","line":"Playful?"},{"who":"Nina","line":"Yes, playful! And on Sundays I go to the… ___ the market in the street, with fruit and vegetables?","gap":"What do you call","options":["What do you call","How do you spell","Where do you buy"]},{"who":"Teacher Ana","line":"A street market! Last question: why do you like Porto Alegre?"},{"who":"Nina","line":"Hmm, ___ Because the people are friendly and there are a lot of parks.","gap":"good question!","options":["good question!","see you later!","you're welcome!"]}]},"mistakes":[{"wrong":"I have 26 years.","options":["I'm 26 years old.","I have 26 years old.","I am 26 years."],"right":"I'm 26 years old.","why":"Idade em inglês usa be: I'm 26 (years old)."},{"wrong":"She don't work on Mondays.","options":["She doesn't work on Mondays.","She doesn't works on Mondays.","She not work on Mondays."],"right":"She doesn't work on Mondays.","why":"Com he / she usamos doesn't, e o verbo fica sem -s."},{"wrong":"Are you work in a bank?","options":["Do you work in a bank?","Does you work in a bank?","Is you work in a bank?"],"right":"Do you work in a bank?","why":"Com outros verbos, a pergunta usa do/does, não be."},{"wrong":"Is cold in Toronto in winter.","options":["It's cold in Toronto in winter.","It cold in Toronto in winter.","Are cold in Toronto in winter."],"right":"It's cold in Toronto in winter.","why":"Em inglês a frase precisa de sujeito: It's cold."},{"wrong":"Have a lot of cafés in my street.","options":["There are a lot of cafés in my street.","There is a lot of cafés in my street.","Has a lot of cafés in my street."],"right":"There are a lot of cafés in my street.","why":"Para dizer que algo existe, use there is / there are, não have."},{"wrong":"I usually am tired on Fridays.","options":["I'm usually tired on Fridays.","I usually tired on Fridays.","Usually I tired on Fridays."],"right":"I'm usually tired on Fridays.","why":"Com o verbo be, o advérbio de frequência vem depois: I'm usually…"}],"pron":{"focus":"th, s or f? (think / sink)","tip":"For th, your tongue is between your teeth. For s, your tongue is behind your teeth. For f, your top teeth touch your lip. Listen and choose the word.","type":"pairs","items":[{"a":"think","b":"sink"},{"a":"thick","b":"sick"},{"a":"mouth","b":"mouse"},{"a":"path","b":"pass"},{"a":"faith","b":"face"},{"a":"thirst","b":"first"},{"a":"thought","b":"fought"}]},"practiceSentences":["Omar is a nurse in Toronto","Does Nina work from home on Mondays","Mei is usually tired after work","Jack doesn't cook at home","There is a park near my house","Where do your parents live","Are you from Ireland","Let me think about that","How do you say this in English"],"readingTime":{"text":"Class magazine: Meet Omar Haddad\nOmar is 34 and he is from Amman, in Jordan. Now he lives in Toronto, Canada, with his wife, Sara, and their daughter, Leila. Sara is a teacher and Leila is five.\nOmar is a nurse at a big hospital. Some weeks he works night shifts, so he sleeps in the day. 'It isn't easy, but I love my job,' he says.\nWhat does he do in his free time? He loves cooking. He often makes Jordanian food for friends, and he always drinks a lot of tea.\nThere is a small park next to their flat. On Sundays, the family usually goes there with a picnic.\nWhy does Omar study English? 'Because I want to talk more with my patients and their families,' he says.\nQuick questions. Coffee or tea? 'Tea, of course!' Morning or night? 'Night. I work at night a lot!'","questions":[{"prompt":"Who is a teacher?","options":["Sara","Leila","Omar"],"correct":"Sara"},{"prompt":"What does the family usually do on Sundays?","options":["They go to the park with a picnic.","They work at the hospital.","They make food for friends."],"correct":"They go to the park with a picnic."}]},"quiz":[{"prompt":"Mei ___ at a bank.","options":["works","is work","work"],"correct":"works","explain":"Present simple with she: verb + -s."},{"prompt":"___ Jack Irish?","options":["Is","Does","Are"],"correct":"Is","explain":"Nationality uses be: Is he Irish?"},{"prompt":"___ Nina have a dog?","options":["Does","Is","Do"],"correct":"Does","explain":"Have is a normal verb: Does she have…?"},{"prompt":"Jack ___ cook. He's a terrible cook!","options":["doesn't","isn't","don't"],"correct":"doesn't","explain":"Negative with he + verb: doesn't."},{"prompt":"___ a lot of trees in the park.","options":["There are","There is","They are"],"correct":"There are","explain":"A lot of trees (plural): there are."},{"prompt":"Omar ___ tired after a night shift.","options":["is usually","usually is","usually"],"correct":"is usually","explain":"With be, the frequency word goes after it."},{"prompt":"You need a moment to answer. You say…","options":["Let me think…","Turn right.","Sounds fun!"],"correct":"Let me think…","explain":"Let me think… gives you time."},{"prompt":"You don't know a word in English. You ask…","options":["How do you say this in English?","How do you do?","How old are you?"],"correct":"How do you say this in English?","explain":"Use How do you say…? to ask for a word."}],"writingPrompt":{"prompt":"Project: the class magazine. Write a profile of a classmate or a friend: name, age, job, home, routine and free time.","help":["This is … He / She is…","He / She lives in… There is…","Every day, he / she…","In his / her free time, he / she usually…"],"words":60}},
  {"n":9,"module":3,"id":"syl-a1-09","title":"Food around the world","emoji":"🍳","description":"Talk about food and drink, use some and any, ask How much and How many, and be a good guest or host","goals":["I can talk about food and drink I like.","I can use some and any with countable and uncountable nouns.","I can ask How much…? and How many…?","I can offer food, say what I don't eat and say the food is delicious."],"grammarTip":"Some nouns are countable: an egg, two eggs. Some are uncountable: milk, rice, bread (no a, no -s). Use some in positive sentences and any in negatives and questions. Ask How many with countable nouns and How much with uncountable nouns.","rules":[{"label":"+ sentences","form":"some","hint":"Positive sentences, with plural or uncountable nouns.","examples":["I have some eggs.","There is some milk in the fridge.","Omar buys some rice."]},{"label":"− and ?","form":"any","hint":"Negative sentences and questions.","examples":["We don't have any bread.","Are there any apples?","Mei doesn't eat any meat."]},{"label":"countable","form":"How many","hint":"With plural nouns: eggs, apples, cups.","examples":["How many eggs do you need?","How many cups of tea does Omar drink?","How many apples are there?"]},{"label":"uncountable","form":"How much","hint":"With uncountable nouns: milk, water, sugar.","examples":["How much milk do we have?","How much water do you drink?","How much sugar is there?"]}],"words":[{"id":"bread","en":"bread","pt":"pão","emoji":"🍞"},{"id":"rice","en":"rice","pt":"arroz","emoji":"🍚"},{"id":"egg","en":"egg","pt":"ovo","emoji":"🥚"},{"id":"cheese","en":"cheese","pt":"queijo","emoji":"🧀"},{"id":"milk","en":"milk","pt":"leite","emoji":"🥛"},{"id":"fruit","en":"fruit","pt":"fruta(s)","emoji":"🍇"},{"id":"apple","en":"apple","pt":"maçã","emoji":"🍎"},{"id":"meat","en":"meat","pt":"carne","emoji":"🥩"},{"id":"fish","en":"fish","pt":"peixe","emoji":"🐟"},{"id":"vegetables","en":"vegetables","pt":"legumes / verduras","emoji":"🥦"},{"id":"sugar","en":"sugar","pt":"açúcar","emoji":"🍬"},{"id":"juice","en":"juice","pt":"suco","emoji":"🧃"},{"id":"vegetarian","en":"vegetarian","pt":"vegetariano(a)","emoji":"🥗"},{"id":"dish","en":"dish","pt":"prato (comida)","emoji":"🍲"},{"id":"delicious","en":"delicious","pt":"delicioso(a)","emoji":"😋"}],"chunks":[{"en":"Help yourself!","pt":"Pode se servir! / Fique à vontade!"},{"en":"This is delicious!","pt":"Isto está delicioso!"},{"en":"I don't eat meat.","pt":"Eu não como carne."},{"en":"I'm vegetarian.","pt":"Sou vegetariano(a)."},{"en":"Can I have some more, please?","pt":"Posso pegar mais um pouco, por favor?"},{"en":"Is there any milk in it?","pt":"Tem leite nisso?"}],"social":{"skill":"Talk about food you don't eat, offer food and say it's good","tip":"When you give food to a guest, say Help yourself! If you don't eat something, say it politely: Sorry, I don't eat meat. And when the food is good, say it: This is delicious!","dialogue":[{"who":"Omar","line":"Come in, Hannah! Dinner is ready. ___","gap":"Help yourself!","options":["Help yourself!","Nice to meet you!","Excuse me!"]},{"who":"Hannah","line":"Thank you! It looks great. What is it?"},{"who":"Omar","line":"It's maqluba, a rice dish from Jordan. There's some chicken in it."},{"who":"Hannah","line":"Oh, sorry. ___","gap":"I don't eat meat.","options":["I don't eat meat.","I don't drink tea.","I don't like Jordan."]},{"who":"Omar","line":"No problem! There's some salad and some bread with hummus. No meat!"},{"who":"Hannah","line":"Mmm, ___","gap":"this hummus is delicious!","options":["this hummus is delicious!","how much is the hummus?","where is the hummus?"]},{"who":"Omar","line":"Thanks! It's my mother's recipe."},{"who":"Hannah","line":"___","gap":"Can I have some more bread, please?","options":["Can I have some more bread, please?","Can I pay for the bread?","Do you sell bread?"]},{"who":"Omar","line":"Of course. Help yourself!"}]},"mistakes":[{"wrong":"I eat a bread every morning.","options":["I eat bread every morning.","I eat breads every morning.","I eat a breads every morning."],"right":"I eat bread every morning.","why":"Bread é incontável em inglês: sem a/an e sem plural."},{"wrong":"How many water do you drink?","options":["How much water do you drink?","How many waters do you drink?","How much waters do you drink?"],"right":"How much water do you drink?","why":"Com incontáveis (water, milk, rice) usamos How much."},{"wrong":"We don't have some eggs.","options":["We don't have any eggs.","We don't have any egg.","We have not some eggs."],"right":"We don't have any eggs.","why":"Em frases negativas usamos any, com o substantivo no plural."},{"wrong":"There are some milk in the fridge.","options":["There is some milk in the fridge.","There are some milks in the fridge.","There is any milk in the fridge."],"right":"There is some milk in the fridge.","why":"Milk é incontável: usamos there is e some."},{"wrong":"Have apples in the kitchen.","options":["There are some apples in the kitchen.","Has apples in the kitchen.","It has apples in the kitchen."],"right":"There are some apples in the kitchen.","why":"Para dizer que algo existe (tem) usamos there is / there are, não have."},{"wrong":"The food is very delicious!","options":["The food is delicious!","The food is much delicious!","The food is very delicious food!"],"right":"The food is delicious!","why":"Delicious já é uma palavra forte: não usamos very antes dela."}],"pron":{"focus":"Short and long vowels: ship or sheep?","tip":"The i in ship is short. The ee in sheep is long. Listen and choose the word you hear. Make the long sound a little longer and smile!","type":"pairs","items":[{"a":"ship","b":"sheep"},{"a":"live","b":"leave"},{"a":"sit","b":"seat"},{"a":"fill","b":"feel"},{"a":"chip","b":"cheap"},{"a":"bin","b":"bean"},{"a":"it","b":"eat"},{"a":"still","b":"steal"}]},"practiceSentences":["We don't have any bread","There is some milk in the fridge","How much water do you drink","How many eggs do you need","Are there any apples","Help yourself to some salad","This soup is delicious","Sorry, I don't eat meat","Can I have some more rice"],"readingTime":{"text":"Breakfast around the world\nWhat do people eat in the morning? We asked four readers.\nAiko, Osaka, Japan: I have some rice, some miso soup and a little fish. I don't have any bread or coffee. I drink green tea.\nLuis, Mexico City: My favourite breakfast is chilaquiles: tortilla chips with some salsa, cheese and an egg. And a big cup of coffee, of course!\nHelen, York, England: On Sundays I have a full English breakfast: eggs, bacon, sausages, beans and toast. On other days I just have some cereal and milk.\nOmar, Toronto, Canada: I'm from Jordan, so I love a Jordanian breakfast: hummus, falafel, bread, cheese and olives. And how many cups of tea? Three!","questions":[{"prompt":"Who doesn't have any bread for breakfast?","options":["Aiko","Luis","Omar"],"correct":"Aiko"},{"prompt":"How many cups of tea does Omar drink?","options":["One","Two","Three"],"correct":"Three"}]},"quiz":[{"prompt":"There is ___ cheese in the fridge.","options":["some","any","many"],"correct":"some","explain":"Positive sentence: some."},{"prompt":"We don't have ___ eggs.","options":["some","any","a"],"correct":"any","explain":"Negative sentence: any."},{"prompt":"How ___ apples do you want?","options":["much","many","any"],"correct":"many","explain":"Apples are countable: How many."},{"prompt":"How ___ sugar do you take?","options":["much","many","some"],"correct":"much","explain":"Sugar is uncountable: How much."},{"prompt":"Your friend is at your home. The food is on the table. You say…","options":["Help yourself!","Excuse me!","See you later!"],"correct":"Help yourself!","explain":"Help yourself! = take the food you want."},{"prompt":"You don't eat meat. You say…","options":["I'm vegetarian.","I'm hungry.","I'm thirsty."],"correct":"I'm vegetarian.","explain":"A vegetarian doesn't eat meat."},{"prompt":"Which word is uncountable?","options":["rice","egg","apple"],"correct":"rice","explain":"We say some rice, not a rice or two rices."}],"writingPrompt":{"prompt":"Write about your favourite breakfast. What do you eat and drink? Is there any food you don't eat?","help":["My favourite breakfast is…","I have some…","I drink…","I don't eat any…"],"words":40}},
  {"n":10,"module":3,"id":"syl-a1-10","title":"Shopping and café","emoji":"☕","description":"Order politely in a café, ask about prices in euros, pounds and dollars, and buy clothes","goals":["I can order food and drink in a café.","I can use I'd like… and Can I have…? to ask politely.","I can ask about prices and say prices in €, £ and $.","I can ask for a size and try clothes on in a shop."],"grammarTip":"To ask politely, say I'd like… (= I would like) or Can I have…? For prices, ask How much is it? for one thing and How much are they? for two or more things. Say prices like this: €3.50 = three euros fifty.","rules":[{"label":"polite order","form":"I'd like","hint":"I'd like = I would like. More polite than I want.","examples":["I'd like a cappuccino, please.","I'd like this T-shirt in blue.","I'd like a small orange juice."]},{"label":"polite question","form":"Can I have","hint":"Can I have + thing + please?","examples":["Can I have a tea, please?","Can I have the bill, please?","Can I have this in a medium?"]},{"label":"price: one thing","form":"How much is","hint":"With one thing.","examples":["How much is this jacket?","How much is a latte?","How much is the blue dress?"]},{"label":"price: plural","form":"How much are","hint":"With plural things: jeans, shoes, two coffees.","examples":["How much are these jeans?","How much are the shoes?","How much are two coffees?"]}],"words":[{"id":"coffee","en":"coffee","pt":"café","emoji":"☕"},{"id":"cake","en":"cake","pt":"bolo","emoji":"🍰"},{"id":"bill","en":"bill","pt":"conta","emoji":"🧾"},{"id":"cash","en":"cash","pt":"dinheiro vivo","emoji":"💵"},{"id":"card","en":"card","pt":"cartão","emoji":"💳"},{"id":"euro","en":"euro (€)","pt":"euro","emoji":"💶"},{"id":"pound","en":"pound (£)","pt":"libra","emoji":"💷"},{"id":"dollar","en":"dollar ($)","pt":"dólar","emoji":"💲"},{"id":"shirt","en":"shirt","pt":"camisa","emoji":"👔"},{"id":"jeans","en":"jeans","pt":"calça jeans","emoji":"👖"},{"id":"jacket","en":"jacket","pt":"jaqueta / casaco","emoji":"🧥"},{"id":"shoes","en":"shoes","pt":"sapatos","emoji":"👟"},{"id":"size","en":"size","pt":"tamanho","emoji":"📏"},{"id":"colour","en":"colour","pt":"cor","emoji":"🎨"},{"id":"changingroom","en":"changing room","pt":"provador","emoji":"🚪"}],"chunks":[{"en":"I'd like a…, please.","pt":"Eu queria um(a)…, por favor."},{"en":"Can I have the bill, please?","pt":"Pode trazer a conta, por favor?"},{"en":"How much is it?","pt":"Quanto custa?"},{"en":"Can I pay by card?","pt":"Posso pagar com cartão?"},{"en":"Can I try it on?","pt":"Posso provar?"},{"en":"Do you have it in a medium?","pt":"Tem no tamanho M?"}],"social":{"skill":"Ask politely in a café and in a shop, pay and try clothes on","tip":"Start with I'd like… or Can I have…? and finish with please. In a shop, ask Can I try it on? before you buy. To pay, ask Can I pay by card?","dialogue":[{"who":"Shop assistant","line":"Hi there! Can I help you?"},{"who":"Mei","line":"Yes, please. ___","gap":"I'd like this jacket in black.","options":["I'd like this jacket in black.","I'm from Taiwan.","Here you are."]},{"who":"Shop assistant","line":"Sure. What size are you?"},{"who":"Mei","line":"Small, I think. ___","gap":"Can I try it on?","options":["Can I try it on?","Can I have the bill?","Can I help you?"]},{"who":"Shop assistant","line":"Of course. The changing rooms are over there."},{"who":"Mei","line":"It's perfect! ___","gap":"How much is it?","options":["How much is it?","How old is it?","Where is it?"]},{"who":"Shop assistant","line":"It's forty-five pounds."},{"who":"Mei","line":"Great. ___","gap":"Can I pay by card?","options":["Can I pay by card?","Do you have it in red?","Can I try it on?"]},{"who":"Shop assistant","line":"Yes, of course. Here's your receipt. Have a nice day!"}]},"mistakes":[{"wrong":"How much costs this shirt?","options":["How much is this shirt?","How much this shirt costs?","How much is cost this shirt?"],"right":"How much is this shirt?","why":"Para perguntar o preço: How much is…? (ou How much does it cost?)."},{"wrong":"I like a cappuccino, please.","options":["I'd like a cappuccino, please.","I liking a cappuccino, please.","I likes a cappuccino, please."],"right":"I'd like a cappuccino, please.","why":"Para pedir, use I'd like (eu queria); I like é 'eu gosto'."},{"wrong":"How much is this jeans?","options":["How much are these jeans?","How much are this jeans?","How much is these jeans?"],"right":"How much are these jeans?","why":"Jeans é plural em inglês: these jeans, How much are…?"},{"wrong":"It's twenty dollar.","options":["It's twenty dollars.","It's dollars twenty.","It's twenty dollar's."],"right":"It's twenty dollars.","why":"Dollars, euros e pounds vão para o plural: twenty dollars."},{"wrong":"Can I prove this jacket?","options":["Can I try on this jacket?","Can I test this jacket on?","Can I prove on this jacket?"],"right":"Can I try on this jacket?","why":"Provar roupa = try on; prove é provar que algo é verdade."},{"wrong":"I'd like a jacket blue.","options":["I'd like a blue jacket.","I'd like a jacket of blue.","I'd like a blues jacket."],"right":"I'd like a blue jacket.","why":"A cor vem antes do substantivo e não tem plural: a blue jacket."}],"pron":{"focus":"Short i or long ee?","tip":"Milk has a short i. Cheese has a long ee. Listen to each word from the café and the shop and put it in the right group.","type":"sort","buckets":["short i (milk)","long ee (cheese)"],"items":[{"text":"milk","say":"milk","bucket":"short i (milk)"},{"text":"chips","say":"chips","bucket":"short i (milk)"},{"text":"fish","say":"fish","bucket":"short i (milk)"},{"text":"drink","say":"drink","bucket":"short i (milk)"},{"text":"pink","say":"pink","bucket":"short i (milk)"},{"text":"big","say":"big","bucket":"short i (milk)"},{"text":"tea","say":"tea","bucket":"long ee (cheese)"},{"text":"green","say":"green","bucket":"long ee (cheese)"},{"text":"jeans","say":"jeans","bucket":"long ee (cheese)"},{"text":"sweet","say":"sweet","bucket":"long ee (cheese)"},{"text":"cheap","say":"cheap","bucket":"long ee (cheese)"},{"text":"three","say":"three","bucket":"long ee (cheese)"}]},"practiceSentences":["I'd like a cappuccino, please","Can I have the bill, please","How much is this jacket","How much are these shoes","Can I pay by card","Can I try it on","Do you have it in blue","It's twelve euros fifty","I'd like a small black coffee"],"readingTime":{"text":"Coffee around the world – Sam's travel blog\nDay 3, Rome: In Italy, people often drink an espresso at the bar, standing up. I say \"Un caffè, per favore\" and it's only about one euro twenty!\nDay 8, Vienna: The coffee houses here are old and beautiful. I'd like a melange, a coffee with milk, and a piece of cake. My coffee comes with a small glass of water, too.\nDay 15, London: Tea or coffee? In London, you can have both! I ask, \"Can I have a flat white, please?\" It's three pounds fifty.\nDay 22, Hanoi, Vietnam: My favourite! Egg coffee: coffee with egg, sugar and milk. It's sweet, like a dessert.\nWhere is your favourite coffee? Tell me in the comments!","questions":[{"prompt":"Where can you drink egg coffee?","options":["Vienna","Hanoi","Rome"],"correct":"Hanoi"},{"prompt":"In Vienna, what comes with Sam's coffee?","options":["a glass of water","an egg","a cup of tea"],"correct":"a glass of water"}]},"quiz":[{"prompt":"___ a hot chocolate, please.","options":["I'd like","I like","I liking"],"correct":"I'd like","explain":"To order, say I'd like… (= I would like)."},{"prompt":"How much ___ these shoes?","options":["is","are","am"],"correct":"are","explain":"Shoes is plural: How much are…?"},{"prompt":"Can I ___ the bill, please?","options":["have","has","having"],"correct":"have","explain":"Can I have…? is a polite question."},{"prompt":"You want to know the price. You say…","options":["How much is it?","How many is it?","How old is it?"],"correct":"How much is it?","explain":"For prices: How much is it?"},{"prompt":"You want to see the jeans on you before you buy. You say…","options":["Can I try them on?","Can I pay by card?","Can I have the bill?"],"correct":"Can I try them on?","explain":"Try on = put clothes on to see them."},{"prompt":"The symbol £ is…","options":["a pound","a euro","a dollar"],"correct":"a pound","explain":"£ = pound (UK), € = euro, $ = dollar."},{"prompt":"The jacket is too small. You say…","options":["Do you have it in a large?","Do you have it in red?","Can I have a coffee?"],"correct":"Do you have it in a large?","explain":"Large is a bigger size."}],"writingPrompt":{"prompt":"You are in a café. Write a short dialogue with the waiter: order a drink and something to eat, ask the price and pay.","help":["Hi! I'd like…","Can I have…?","How much is…?","Can I pay by…?"],"words":40}},
  {"n":11,"module":3,"id":"syl-a1-11","title":"Abilities: can and can't","emoji":"💪","description":"Say what you can and can't do, ask Can you…?, talk about strong and weak points and encourage a friend","goals":["I can say what I can and can't do.","I can ask and answer Can you…? questions.","I can say how well I do things: very well, a little, not at all.","I can talk about my weak points with I can't… yet and encourage a friend."],"grammarTip":"Can is the same for all people: I can, she can, they can. After can, use the verb with no to: I can swim. The negative is can't. For questions, put can first: Can you drive? Yes, I can. / No, I can't.","rules":[{"label":"+ yes","form":"can","hint":"Same for I, you, he, she, we, they. No to after can.","examples":["I can swim.","Mei can play the piano.","Omar can cook very well."]},{"label":"− no","form":"can't","hint":"can't = cannot. Add yet: you want to learn.","examples":["Jack can't cook.","I can't drive yet.","Leila can't read yet."]},{"label":"? question","form":"Can you","hint":"Can first, then the person. Answer: Yes, I can. / No, I can't.","examples":["Can you swim?","Can you speak Spanish?","Can you play the guitar?"]}],"words":[{"id":"swim","en":"swim","pt":"nadar","emoji":"🏊"},{"id":"cook","en":"cook","pt":"cozinhar","emoji":"👨‍🍳"},{"id":"drive","en":"drive","pt":"dirigir","emoji":"🚗"},{"id":"dance","en":"dance","pt":"dançar","emoji":"💃"},{"id":"sing","en":"sing","pt":"cantar","emoji":"🎤"},{"id":"ridebike","en":"ride a bike","pt":"andar de bicicleta","emoji":"🚲"},{"id":"playpiano","en":"play the piano","pt":"tocar piano","emoji":"🎹"},{"id":"speak","en":"speak","pt":"falar (um idioma)","emoji":"🗣️"},{"id":"draw","en":"draw","pt":"desenhar","emoji":"✏️"},{"id":"fix","en":"fix","pt":"consertar","emoji":"🔧"},{"id":"skill","en":"skill","pt":"habilidade","emoji":"⭐"},{"id":"well","en":"well","pt":"bem","emoji":"👍"},{"id":"alittle","en":"a little","pt":"um pouco","emoji":"🤏"},{"id":"notatall","en":"not at all","pt":"nem um pouco / nada","emoji":"🚫"}],"chunks":[{"en":"I can't… yet, but I'm learning.","pt":"Ainda não sei…, mas estou aprendendo."},{"en":"I'm good at…","pt":"Sou bom / boa em…"},{"en":"I'm not very good at…","pt":"Não sou muito bom / boa em…"},{"en":"How well can you…?","pt":"Você sabe… bem?"},{"en":"You can do it!","pt":"Você consegue!"},{"en":"Well done!","pt":"Muito bem! / Parabéns!"}],"social":{"skill":"Talk about strong and weak points and encourage someone","tip":"It's OK to say what you can't do. Add yet: I can't swim yet. It means you want to learn. When a friend is learning something, say You can do it! or Well done!","dialogue":[{"who":"Jack","line":"Mei, can you play an instrument?"},{"who":"Mei","line":"Yes, I can play the piano. ___","gap":"What about you?","options":["What about you?","How much is it?","Nice to meet you."]},{"who":"Jack","line":"Me? I'm learning the guitar now. It's hard!"},{"who":"Mei","line":"___","gap":"You can do it!","options":["You can do it!","You can't do it.","Can you do it?"]},{"who":"Jack","line":"Thanks! I can play three songs now… badly!"},{"who":"Mei","line":"___ That's a good start.","gap":"Well done!","options":["Well done!","Excuse me!","Help yourself!"]},{"who":"Jack","line":"And you? What can't you do?"},{"who":"Mei","line":"Oh, I'm not very good at sports. ___","gap":"I can't swim yet.","options":["I can't swim yet.","I can swim very well.","I'm good at sports."]},{"who":"Jack","line":"Swimming is fun! You can do it, Mei!"}]},"mistakes":[{"wrong":"I can to swim.","options":["I can swim.","I can swimming.","I cans swim."],"right":"I can swim.","why":"Depois de can o verbo vem sem to: can swim."},{"wrong":"She cans play the piano.","options":["She can play the piano.","She can plays the piano.","She cans plays the piano."],"right":"She can play the piano.","why":"Can não muda com he / she: she can (sem -s), e o verbo também fica sem -s."},{"wrong":"You can speak English?","options":["Can you speak English?","Do you can speak English?","Can you speaks English?"],"right":"Can you speak English?","why":"Na pergunta, can vem antes do sujeito: Can you…?"},{"wrong":"I don't can drive.","options":["I can't drive.","I can't to drive.","I not can drive."],"right":"I can't drive.","why":"A negativa de can é can't (cannot), sem don't."},{"wrong":"I can speak English very good.","options":["I can speak English very well.","I can very well speak English.","I can speak English very goodly."],"right":"I can speak English very well.","why":"Para dizer como você faz algo, use well (bem), no fim da frase."},{"wrong":"Leila can't read still.","options":["Leila can't read yet.","Leila can't read already.","Leila still can't read yet."],"right":"Leila can't read yet.","why":"Para 'ainda não' no fim da frase negativa, use yet."}],"pron":{"focus":"can or can't?","tip":"In a sentence, can is short and weak: I c'n swim. Can't is long and strong, with a clear vowel. Listen to the vowel and choose can or can't.","type":"pairs","items":[{"a":"I can swim.","b":"I can't swim."},{"a":"She can drive.","b":"She can't drive."},{"a":"He can cook.","b":"He can't cook."},{"a":"We can dance.","b":"We can't dance."},{"a":"They can sing.","b":"They can't sing."},{"a":"I can draw.","b":"I can't draw."},{"a":"You can come.","b":"You can't come."}]},"practiceSentences":["I can play the piano","Jack can't cook at all","Can you speak Spanish","Omar can cook very well","I can't drive yet","Can she ride a bike","Yes, she can","You can do it","How well can you swim","I'm good at drawing"],"readingTime":{"text":"Swimming lessons: a Dutch tradition\nAMSTERDAM – In the Netherlands, there is water everywhere: canals, rivers, lakes and the sea. So swimming is very important here.\nMost Dutch children have swimming lessons when they are five or six. At the end, they take a test for their first swimming diploma, the \"A diploma\".\nIn the test, children swim in their clothes and shoes! They also swim under water.\n\"Our son Daan is six. He can swim very well now, and he can swim in his clothes,\" says his mother, Femke. \"He's very proud.\"\nAnd Daan's dad? \"I can swim, but not very well,\" he says. \"Maybe I need lessons too!\"","questions":[{"prompt":"When do most Dutch children have swimming lessons?","options":["at five or six","at twelve","at eighteen"],"correct":"at five or six"},{"prompt":"Who can't swim very well?","options":["Daan","Daan's dad","Femke"],"correct":"Daan's dad"}]},"quiz":[{"prompt":"Omar ___ cook very well.","options":["can","cans","can to"],"correct":"can","explain":"Can is the same for all people, and no to after it."},{"prompt":"___ you play the guitar?","options":["Do","Can","Are"],"correct":"Can","explain":"Questions about ability: Can you…?"},{"prompt":"Can you swim? – No, I ___.","options":["can","can't","don't"],"correct":"can't","explain":"Short answer: No, I can't."},{"prompt":"I can speak English, but not very ___.","options":["well","good","yet"],"correct":"well","explain":"How you do something: well."},{"prompt":"Jack can't cook at all. He's a ___ cook.","options":["terrible","great","good"],"correct":"terrible","explain":"Not at all = zero. He's a terrible cook."},{"prompt":"Your friend is nervous about a test. You say…","options":["You can do it!","You can't do it.","Can you do it?"],"correct":"You can do it!","explain":"You can do it! encourages a friend."},{"prompt":"You don't drive now, but you want to learn. You say…","options":["I can't drive yet.","I can drive very well.","I can't drive at all and I don't want to."],"correct":"I can't drive yet.","explain":"Yet = not now, but in the future."}],"writingPrompt":{"prompt":"Write about your skills. What can you do well? What can't you do yet? What do you want to learn?","help":["I can… very well.","I'm good at…","I can't… yet.","I want to learn to…"],"words":40}},
  {"n":12,"module":3,"id":"syl-a1-12","title":"Right now: present continuous","emoji":"🌦️","description":"Say what people are doing right now, talk about the weather and answer the phone when you're busy","goals":["I can say what people are doing right now.","I can use am, is and are + -ing.","I can see the difference between I work (routine) and I'm working (now).","I can talk about the weather and answer a call when I'm busy."],"grammarTip":"For actions now, use am / is / are + verb-ing: I'm working. It's raining. For routines, use the present simple: I work every day. Now, right now and today often go with -ing; usually, every day and on Saturdays go with the present simple.","rules":[{"label":"I","form":"am","hint":"I am + -ing. Short form: I'm.","examples":["I am cooking dinner.","I am working from home today.","I am waiting for the bus."]},{"label":"he / she / it","form":"is","hint":"is + -ing. Short form: he's, she's, it's.","examples":["It is raining in Dublin.","Omar is sleeping now.","Mei is drinking bubble tea."]},{"label":"you / we / they","form":"are","hint":"are + -ing. Question: What are you doing?","examples":["We are watching the football.","They are playing volleyball.","What are you doing?"]},{"label":"routine","form":"usually","hint":"Routines use the present simple, not -ing.","examples":["I usually walk to work.","Jack usually gets up late.","We usually have lunch at one."]}],"words":[{"id":"raining","en":"It's raining.","pt":"Está chovendo.","emoji":"🌧️"},{"id":"snowing","en":"It's snowing.","pt":"Está nevando.","emoji":"🌨️"},{"id":"sunny","en":"sunny","pt":"ensolarado","emoji":"☀️"},{"id":"cloudy","en":"cloudy","pt":"nublado","emoji":"☁️"},{"id":"windy","en":"windy","pt":"com vento","emoji":"💨"},{"id":"cold","en":"cold","pt":"frio","emoji":"🥶"},{"id":"warm","en":"warm","pt":"quente (agradável)","emoji":"🌤️"},{"id":"umbrella","en":"umbrella","pt":"guarda-chuva","emoji":"☂️"},{"id":"waiting","en":"waiting","pt":"esperando","emoji":"⏳"},{"id":"sleeping","en":"sleeping","pt":"dormindo","emoji":"😴"},{"id":"watching","en":"watching","pt":"assistindo","emoji":"📺"},{"id":"wearing","en":"wearing","pt":"vestindo / usando (roupa)","emoji":"🧣"},{"id":"busy","en":"busy","pt":"ocupado(a)","emoji":"📵"},{"id":"rightnow","en":"right now","pt":"agora mesmo","emoji":"⏱️"}],"chunks":[{"en":"Hang on a second!","pt":"Espera um segundo!"},{"en":"I'm on my way!","pt":"Tô a caminho! / Tô indo!"},{"en":"I'm busy right now.","pt":"Estou ocupado(a) agora."},{"en":"Can I call you back?","pt":"Posso te ligar depois?"},{"en":"What are you doing?","pt":"O que você está fazendo?"},{"en":"See you in five minutes!","pt":"Te vejo em cinco minutos!"}],"social":{"skill":"Answer a call or message when you're busy","tip":"When you need a moment, say Hang on a second! When you are going to meet someone and you're late, say I'm on my way! If you can't talk now, say I'm busy right now. Can I call you back?","dialogue":[{"who":"Caio","line":"Hi, Nina! It's Caio. What are you doing?"},{"who":"Nina","line":"Oh, hi! ___ I'm looking for my keys.","gap":"Hang on a second!","options":["Hang on a second!","See you later!","Help yourself!"]},{"who":"Nina","line":"OK, here they are. Sorry! I'm going out. My volleyball friends are waiting for me."},{"who":"Caio","line":"Well, I'm sitting in a café near your flat. I'm visiting Porto Alegre this weekend. Surprise!"},{"who":"Nina","line":"What? Really? ___ Which café?","gap":"I'm on my way!","options":["I'm on my way!","I'm from Recife!","I'm good at it!"]},{"who":"Caio","line":"The small café on the corner, near the park."},{"who":"Nina","line":"Great! I can stay for ten minutes. ___","gap":"See you in five minutes!","options":["See you in five minutes!","Nice to meet you!","Good night!"]},{"who":"Caio","line":"Perfect! I'm ordering a coffee for you now."}]},"mistakes":[{"wrong":"I working now.","options":["I'm working now.","I'm work now.","I am works now."],"right":"I'm working now.","why":"No present continuous precisamos de am / is / are + verbo com -ing."},{"wrong":"Is raining in London.","options":["It's raining in London.","Raining in London.","Is rain in London."],"right":"It's raining in London.","why":"Em inglês o sujeito não some, nem para o tempo: It's raining."},{"wrong":"She is play tennis now.","options":["She is playing tennis now.","She play tennis now.","She is plays tennis now."],"right":"She is playing tennis now.","why":"Depois de am / is / are o verbo leva -ing."},{"wrong":"What you are doing?","options":["What are you doing?","What do you doing?","What you doing are?"],"right":"What are you doing?","why":"Na pergunta, are vem antes de you."},{"wrong":"I'm usually getting up at seven.","options":["I usually get up at seven.","I usually getting up at seven.","I'm usually get up at seven."],"right":"I usually get up at seven.","why":"Para rotina use o present simple, não o -ing."},{"wrong":"I'm making my homework now.","options":["I'm doing my homework now.","I'm make my homework now.","I'm doing my homeworks now."],"right":"I'm doing my homework now.","why":"Dever de casa é do homework (não make), e homework não tem plural."}],"pron":{"focus":"Short and long vowels in -ing words","tip":"In living, the i is short. In leaving, the ee is long. Listen and choose the word you hear. The same is true for full (short) and fool (long).","type":"pairs","items":[{"a":"living","b":"leaving"},{"a":"slipping","b":"sleeping"},{"a":"filling","b":"feeling"},{"a":"hitting","b":"heating"},{"a":"sitting","b":"seating"},{"a":"full","b":"fool"},{"a":"pull","b":"pool"}]},"practiceSentences":["I'm working from home today","It's raining in Dublin","What are you doing right now","Omar is sleeping after his shift","They are playing volleyball in the park","Hang on a second","I'm on my way","Jack usually gets up late","Mei is waiting for the bus"],"readingTime":{"text":"Live blog: Saturday, 12 noon in London – what's happening around the world?\nLondon and Dublin, 12:00: It's cloudy and cold. In Dublin, Jack Moore is having breakfast – he's a night owl! His sons are watching football on TV.\nToronto, 7:00: It's cold and windy. Omar is coming home after a night shift. He's tired, but he's making a cup of tea.\nPorto Alegre, 9:00: It's sunny and warm. Nina is walking her dog, Pipoca, in the park. Her volleyball friends are waiting for her.\nDubai, 16:00: It's hot and sunny. Fatima is sitting in a café with her friends.\nTaipei, 20:00: It's raining. Mei is drinking bubble tea and studying English.\nSydney, 23:00: It's a warm night. Ben and Chloe are dancing at a friend's birthday party.","questions":[{"prompt":"Where is it raining?","options":["Taipei","Dubai","Sydney"],"correct":"Taipei"},{"prompt":"What is Omar doing?","options":["He's making tea.","He's walking his dog.","He's watching football."],"correct":"He's making tea."}]},"quiz":[{"prompt":"Look! It ___ raining.","options":["is","are","am"],"correct":"is","explain":"It takes is: It's raining."},{"prompt":"Shh! The baby ___.","options":["is sleeping","sleeps","sleep"],"correct":"is sleeping","explain":"Shh! = now. Use is + -ing."},{"prompt":"Jack ___ late every Sunday.","options":["gets up","is getting up","get up"],"correct":"gets up","explain":"Every Sunday = routine: present simple."},{"prompt":"What ___ you doing now?","options":["are","do","is"],"correct":"are","explain":"What are you doing? = action now."},{"prompt":"It's cold and everything is white outside. It's ___.","options":["snowing","sunny","hot"],"correct":"snowing","explain":"White and cold: it's snowing."},{"prompt":"Your friend calls. You need one moment. You say…","options":["Hang on a second!","Help yourself!","Nice to meet you!"],"correct":"Hang on a second!","explain":"Hang on a second! = wait a moment."},{"prompt":"You're late. Your friend is waiting for you. You say…","options":["I'm on my way!","I'm at home!","I'm in the way!"],"correct":"I'm on my way!","explain":"I'm on my way! = I'm going there now."}],"writingPrompt":{"prompt":"It's Saturday afternoon. Write a message to a friend: Where are you? What's the weather like? What are you and the people around you doing?","help":["Hi! I'm at…","It's sunny / raining / cold…","I'm …ing","My … is / are …ing"],"words":40}},
  {"n":13,"module":4,"id":"syl-a1-13","title":"Comparing places and things","emoji":"⚖️","description":"Compare people, places and things, and give your opinion","goals":["I can compare two things with -er and than.","I can use more with long adjectives: more expensive.","I can say the biggest, the best and the most beautiful.","I can give my opinion and say what I prefer."],"grammarTip":"Short adjectives take -er + than: Jack is older than Mei. Long adjectives take more: Tokyo is more expensive than Taipei. For number one, use the + -est or the most: the biggest, the most beautiful. Good is different: good, better, the best.","rules":[{"label":"short adjectives","form":"than","hint":"Add -er, then than. big → bigger, easy → easier.","examples":["Jack is older than Mei.","Toronto is colder than Recife.","Mei is younger than Omar."]},{"label":"long adjectives","form":"more","hint":"Long adjectives: more + adjective + than.","examples":["Tokyo is more expensive than Taipei.","For me, hiking is more interesting than running.","My new job is more difficult."]},{"label":"number one","form":"the most","hint":"Long adjectives: the most. Short ones: the + -est (the biggest).","examples":["For me, Galway is the most beautiful city in Ireland.","This is the most popular café in town.","Who is the most patient person in your family?"]},{"label":"good → better","form":"better","hint":"Good → better → the best. Bad → worse → the worst.","examples":["Omar is a better cook than Jack.","My English is better now.","Is tea better than coffee?"]}],"words":[{"id":"big","en":"big","pt":"grande","emoji":"🐘"},{"id":"small","en":"small","pt":"pequeno","emoji":"🐭"},{"id":"tall","en":"tall","pt":"alto (pessoa, prédio)","emoji":"🦒"},{"id":"fast","en":"fast","pt":"rápido","emoji":"🐆"},{"id":"slow","en":"slow","pt":"lento","emoji":"🐢"},{"id":"expensive","en":"expensive","pt":"caro","emoji":"💰"},{"id":"cheap","en":"cheap","pt":"barato","emoji":"🏷️"},{"id":"mountain","en":"mountain","pt":"montanha","emoji":"⛰️"},{"id":"river","en":"river","pt":"rio","emoji":"🏞️"},{"id":"ocean","en":"ocean","pt":"oceano","emoji":"🌊"},{"id":"desert","en":"desert","pt":"deserto","emoji":"🏜️"},{"id":"island","en":"island","pt":"ilha","emoji":"🏝️"},{"id":"thousand","en":"a thousand","pt":"mil","emoji":"🔢"},{"id":"million","en":"a million","pt":"um milhão","emoji":"💯"},{"id":"opinion","en":"opinion","pt":"opinião","emoji":"💭"}],"chunks":[{"en":"In my opinion…","pt":"Na minha opinião…"},{"en":"I prefer… because…","pt":"Eu prefiro… porque…"},{"en":"I think it's better.","pt":"Acho que é melhor."},{"en":"Which one do you prefer?","pt":"Qual você prefere?"},{"en":"What do you think?","pt":"O que você acha?"},{"en":"It's the best!","pt":"É o melhor!"}],"social":{"skill":"Give your opinion and say what you prefer","tip":"To give your opinion, start with In my opinion… or I think… To say what you like more, say I prefer… and give a reason with because. Then ask the others: What do you think?","dialogue":[{"who":"Ana","line":"OK, a question for everyone: the beach or the mountains?"},{"who":"Mei","line":"___ the mountains because I love hiking.","gap":"I prefer","options":["I prefer","I don't like","I'm afraid of"]},{"who":"Jack","line":"Really? I think the beach is better. It's more relaxing."},{"who":"Mei","line":"But the mountains are quieter. ___","gap":"What do you think, Omar?","options":["What do you think, Omar?","Where are you, Omar?","Goodbye, Omar."]},{"who":"Omar","line":"___, the beach is better. I like hot weather.","gap":"In my opinion","options":["In my opinion","In my house","On my way"]},{"who":"Jack","line":"See? Two for the beach!"},{"who":"Mei","line":"OK, OK. But the mountains are the most beautiful places in the world!"},{"who":"Ana","line":"Great opinions! ___, Nina?","gap":"Which one do you prefer","options":["Which one do you prefer","How old are you","Where do you work"]}]},"mistakes":[{"wrong":"Toronto is more big than Dublin.","options":["Toronto is bigger than Dublin.","Toronto is more bigger than Dublin.","Toronto is biger than Dublin."],"right":"Toronto is bigger than Dublin.","why":"Adjetivo curto ganha -er (big → bigger), sem more."},{"wrong":"My English is more good now.","options":["My English is better now.","My English is gooder now.","My English is more better now."],"right":"My English is better now.","why":"Good é irregular: good → better → the best."},{"wrong":"Jack is older that Mei.","options":["Jack is older than Mei.","Jack is older of Mei.","Jack is older as Mei."],"right":"Jack is older than Mei.","why":"Para comparar duas coisas usamos than (= do que)."},{"wrong":"Tokyo is expensiver than Taipei.","options":["Tokyo is more expensive than Taipei.","Tokyo is expensivest than Taipei.","Tokyo is most expensive than Taipei."],"right":"Tokyo is more expensive than Taipei.","why":"Adjetivos longos usam more: more expensive than."},{"wrong":"Everest is the most high mountain in the world.","options":["Everest is the highest mountain in the world.","Everest is the more high mountain in the world.","Everest is the higher mountain of the world."],"right":"Everest is the highest mountain in the world.","why":"No superlativo, adjetivo curto fica the + -est: the highest."},{"wrong":"I prefer the beach than the mountains.","options":["I prefer the beach to the mountains.","I prefer the beach that the mountains.","I prefer more the beach than the mountains."],"right":"I prefer the beach to the mountains.","why":"Com prefer usamos to: I prefer X to Y."}],"pron":{"focus":"Short or long adjective: -er or more?","tip":"Listen and count the syllables. Short adjectives with one syllable (big, cold) take -er. Long adjectives (expensive, beautiful) take more. Listen and sort.","type":"sort","buckets":["one syllable: -er","long: more"],"items":[{"text":"big","say":"big","bucket":"one syllable: -er"},{"text":"cold","say":"cold","bucket":"one syllable: -er"},{"text":"fast","say":"fast","bucket":"one syllable: -er"},{"text":"cheap","say":"cheap","bucket":"one syllable: -er"},{"text":"old","say":"old","bucket":"one syllable: -er"},{"text":"tall","say":"tall","bucket":"one syllable: -er"},{"text":"expensive","say":"expensive","bucket":"long: more"},{"text":"beautiful","say":"beautiful","bucket":"long: more"},{"text":"interesting","say":"interesting","bucket":"long: more"},{"text":"popular","say":"popular","bucket":"long: more"},{"text":"difficult","say":"difficult","bucket":"long: more"},{"text":"relaxing","say":"relaxing","bucket":"long: more"}]},"practiceSentences":["Toronto is colder than Recife","Jack is older than Mei","Tokyo is more expensive than Taipei","Omar is a better cook than Jack","In my opinion, the beach is better","I prefer the mountains because they are quiet","Which one do you prefer","The Pacific is the biggest ocean","Everest is the highest mountain in the world","Is tea better than coffee"],"readingTime":{"text":"World records: the biggest, the highest, the fastest\nWhat is the biggest country in the world? It's Russia. It's bigger than Canada, China and the USA.\nAnd the smallest country? It's Vatican City, in Rome. It's very, very small: less than 1,000 people live there.\nMount Everest, in Asia, is the highest mountain in the world. It's 8,849 metres high. A lot of people climb it, but it's difficult and dangerous.\nThe Pacific is the biggest ocean. It's bigger than all the land on Earth!\nThe cheetah is the fastest animal on land. It's faster than a car in the city.\nThe blue whale is the biggest animal in history. It's bigger than the dinosaurs!\nWhich record is the most interesting for you?","questions":[{"prompt":"What is the smallest country in the world?","options":["Vatican City","Russia","Canada"],"correct":"Vatican City"},{"prompt":"What is the fastest animal on land?","options":["the cheetah","the blue whale","the horse"],"correct":"the cheetah"}]},"quiz":[{"prompt":"In July, Toronto is hot, but in January it's ___ than Recife.","options":["colder","more cold","coldest"],"correct":"colder","explain":"Cold is short: colder than."},{"prompt":"Tokyo is ___ than Taipei.","options":["expensiver","more expensive","most expensive"],"correct":"more expensive","explain":"Expensive is long: more expensive than."},{"prompt":"Omar is a ___ cook than Jack.","options":["good","better","best"],"correct":"better","explain":"Two people: good becomes better."},{"prompt":"Everest is ___ mountain in the world.","options":["the highest","higher","the most high"],"correct":"the highest","explain":"Number one, short adjective: the + -est."},{"prompt":"Jack is older ___ Mei.","options":["than","that","of"],"correct":"than","explain":"We compare two people with than."},{"prompt":"The opposite of cheap is…","options":["expensive","small","slow"],"correct":"expensive","explain":"Cheap ↔ expensive."},{"prompt":"You want to give your opinion. You say…","options":["In my opinion, Dublin is beautiful.","In my opinion, is beautiful Dublin.","On my opinion Dublin beautiful."],"correct":"In my opinion, Dublin is beautiful.","explain":"In my opinion + a full sentence (subject + verb)."},{"prompt":"Your friend asks: Tea or coffee? You say…","options":["I prefer tea because it's relaxing.","I'm prefer tea.","I am tea, please."],"correct":"I prefer tea because it's relaxing.","explain":"I prefer… because… No am before prefer."}],"writingPrompt":{"prompt":"Compare two cities or places you know. Which one do you prefer? Why?","help":["In my opinion, …","… is bigger / more … than …","The best thing about … is …","I prefer … because …"],"words":40}},
  {"n":14,"module":4,"id":"syl-a1-14","title":"Where were you yesterday?","emoji":"🕰️","description":"Talk about the past with was and were, there was / there were, and dates","goals":["I can use was and were to talk about the past.","I can say there was and there were.","I can use yesterday, last week, in 1999 and two years ago.","I can ask How was your weekend? and say I don't remember."],"grammarTip":"The past of be has two forms: I / he / she / it was, and you / we / they were. The negative is wasn't and weren't. For a question, put the verb first: Were you at home? Where was she?","rules":[{"label":"I / he / she / it","form":"was","hint":"One person or thing. Negative: wasn't.","examples":["I was at home yesterday.","Mei was tired on Monday.","The film was great."]},{"label":"you / we / they","form":"were","hint":"You, and more than one person. Negative: weren't.","examples":["We were in class last night.","Where were you on Saturday?","Jack's sons were at school."]},{"label":"negative","form":"wasn't","hint":"was + not = wasn't (were + not = weren't).","examples":["It wasn't cold in Recife.","Omar wasn't at work yesterday.","The hotel wasn't expensive."]},{"label":"many things in the past","form":"there were","hint":"There was + one thing. There were + many things.","examples":["There were ten people at the party.","There were no buses on Sunday.","There were two cafés near my old house."]}],"words":[{"id":"yesterday","en":"yesterday","pt":"ontem","emoji":"📅"},{"id":"lastnight","en":"last night","pt":"ontem à noite","emoji":"🌙"},{"id":"lastweek","en":"last week","pt":"semana passada","emoji":"🗓️"},{"id":"ago","en":"ago","pt":"atrás (two years ago = há dois anos)","emoji":"⏪"},{"id":"weekend","en":"weekend","pt":"fim de semana","emoji":"🛋️"},{"id":"tired","en":"tired","pt":"cansado","emoji":"😴"},{"id":"bored","en":"bored","pt":"entediado","emoji":"🥱"},{"id":"excited","en":"excited","pt":"animado","emoji":"🤩"},{"id":"nervous","en":"nervous","pt":"nervoso","emoji":"😬"},{"id":"angry","en":"angry","pt":"bravo, com raiva","emoji":"😠"},{"id":"born","en":"born","pt":"nascido (I was born = eu nasci)","emoji":"👶"},{"id":"year","en":"year","pt":"ano","emoji":"🎆"},{"id":"first","en":"the first","pt":"o primeiro","emoji":"🥇"},{"id":"remember","en":"remember","pt":"lembrar","emoji":"🧠"}],"chunks":[{"en":"How was your weekend?","pt":"Como foi seu fim de semana?"},{"en":"It was great, thanks.","pt":"Foi ótimo, obrigado(a)."},{"en":"Sorry, I don't remember.","pt":"Desculpa, não lembro."},{"en":"I can't remember the name.","pt":"Não consigo lembrar o nome."},{"en":"Where were you?","pt":"Onde você estava?"},{"en":"I was born in…","pt":"Eu nasci em…"}],"social":{"skill":"Ask how something was and say you don't remember","tip":"On Monday, ask a friend How was your weekend? Answer with It was great, It was OK or It was boring. If you forget something, don't worry: say Sorry, I don't remember or I can't remember.","dialogue":[{"who":"Nina","line":"Hi, Omar! ___","gap":"How was your weekend?","options":["How was your weekend?","How old are you?","What's your job?"]},{"who":"Omar","line":"It was great, thanks! We were at the lake with Leila. What about you?"},{"who":"Nina","line":"It was OK. I was at home on Sunday. It was very cold in Porto Alegre."},{"who":"Omar","line":"Oh! Were you at volleyball on Saturday?"},{"who":"Nina","line":"Yes, ___ We were in a small tournament.","gap":"I was.","options":["I was.","I am.","it was."]},{"who":"Omar","line":"Cool! What was the name of the other team?"},{"who":"Nina","line":"Hmm… ___ Something with 'Sol'…","gap":"I can't remember.","options":["I can't remember.","I don't know you.","I'm not tired."]},{"who":"Omar","line":"Ha! No problem. Were you the winners?"},{"who":"Nina","line":"No, we weren't. But ___","gap":"it was a lot of fun!","options":["it was a lot of fun!","it is very late!","they were at home!"]}]},"mistakes":[{"wrong":"I born in 1997.","options":["I was born in 1997.","I am born in 1997.","I borned in 1997."],"right":"I was born in 1997.","why":"Para dizer quando ou onde nasceu: I was born (com was)."},{"wrong":"They was at home.","options":["They were at home.","They are at home yesterday.","They be at home."],"right":"They were at home.","why":"Com you, we e they usamos were."},{"wrong":"Was cold yesterday.","options":["It was cold yesterday.","Was it cold yesterday.","It cold yesterday."],"right":"It was cold yesterday.","why":"A frase em inglês precisa de sujeito: It was cold."},{"wrong":"Had a lot of people at the party.","options":["There were a lot of people at the party.","There was a lot of people at the party.","It had a lot of people at the party."],"right":"There were a lot of people at the party.","why":"'Tinha / havia' no passado é there was / there were, não had."},{"wrong":"You were at home yesterday?","options":["Were you at home yesterday?","Was you at home yesterday?","You was at home yesterday?"],"right":"Were you at home yesterday?","why":"Na pergunta, was / were vem antes do sujeito."},{"wrong":"I was in Lisbon has two years.","options":["I was in Lisbon two years ago.","I was in Lisbon ago two years.","I was in Lisbon there are two years."],"right":"I was in Lisbon two years ago.","why":"'Há dois anos' em inglês é two years ago, com ago no final."}],"pron":{"focus":"was / wasn't, were / weren't","tip":"In a sentence, was and were are short and quick. Wasn't and weren't are longer and strong, with a t at the end. Listen and choose.","type":"pairs","items":[{"a":"It was cold.","b":"It wasn't cold."},{"a":"She was at home.","b":"She wasn't at home."},{"a":"We were late.","b":"We weren't late."},{"a":"They were tired.","b":"They weren't tired."},{"a":"The film was good.","b":"The film wasn't good."},{"a":"You were right.","b":"You weren't right."},{"a":"He was happy.","b":"He wasn't happy."}]},"practiceSentences":["I was at home yesterday","Where were you last night","How was your weekend","It was cold in Dublin","We weren't at the party","There were many people at the beach","Nina was born in Recife","Sorry, I don't remember","Was the hotel expensive","The film was really good"],"readingTime":{"text":"Famous firsts\nThe first photo: It was in France, in the 1820s. The camera was open for many hours, so the photo isn't very clear. It's a view from a window.\nThe first website: It was in 1991, in Switzerland. There were no pictures and there were no colours. There was only text, and it was about the web.\nThe first text message: It was in 1992, in the UK. It was only two words: 'Merry Christmas'. It wasn't from a phone. It was from a computer!\nThe first famous emoji: They were from Japan, in 1999. There were 176 emoji, and they were very small and simple.\nToday there are billions of photos, websites, messages and emoji. But these were the first!","questions":[{"prompt":"Where was the first website?","options":["in Switzerland","in Japan","in the UK"],"correct":"in Switzerland"},{"prompt":"The first text message was from…","options":["a computer","a phone","a camera"],"correct":"a computer"}]},"quiz":[{"prompt":"Mei ___ tired yesterday.","options":["was","were","is"],"correct":"was","explain":"One person (she) in the past: was."},{"prompt":"Where ___ you last night?","options":["was","were","are"],"correct":"were","explain":"You + past: were."},{"prompt":"___ ten people at the party.","options":["There were","There was","It had"],"correct":"There were","explain":"Many people in the past: there were."},{"prompt":"Omar ___ at work yesterday. He was at home.","options":["wasn't","weren't","isn't"],"correct":"wasn't","explain":"He + negative past: wasn't."},{"prompt":"I was in Japan three years ___.","options":["ago","last","before"],"correct":"ago","explain":"Three years ago = há três anos. Ago goes at the end."},{"prompt":"The film was long and not interesting. I was…","options":["bored","excited","born"],"correct":"bored","explain":"Not interesting → bored."},{"prompt":"It's Monday. You want to ask about your friend's Saturday and Sunday. You say…","options":["How was your weekend?","How is your weekend?","Where is your weekend?"],"correct":"How was your weekend?","explain":"The weekend is in the past: How was…?"},{"prompt":"You forget a name. You say…","options":["Sorry, I can't remember.","Sorry, I don't know you.","Sorry, I was tired."],"correct":"Sorry, I can't remember.","explain":"I can't remember / I don't remember."}],"writingPrompt":{"prompt":"Write about last weekend: where were you, who were you with, and how was it?","help":["Last weekend I was…","I was with…","There was / There were…","It was … because…"],"words":40}},
  {"n":15,"module":4,"id":"syl-a1-15","title":"Past simple: my trip","emoji":"✈️","description":"Talk about a trip with regular and irregular past verbs and didn't","goals":["I can use regular past verbs: visited, walked, stayed.","I can use common irregular verbs: went, had, saw, ate.","I can say what I didn't do with didn't + verb.","I can tell someone about a trip: The best part was…"],"grammarTip":"For the past, add -ed to regular verbs: visit → visited, walk → walked. Many common verbs are irregular: go → went, have → had, see → saw, eat → ate. The negative is didn't + verb: I didn't go (not I didn't went).","rules":[{"label":"regular verbs","form":"visited","hint":"Regular verbs: + -ed. visit → visited, stay → stayed.","examples":["Nina visited Lisbon in June.","We visited a beautiful old church.","I visited my brother last month."]},{"label":"go → went","form":"went","hint":"Irregular. The same for I, you, he, she, we, they.","examples":["We went to the beach.","Mei went hiking on Sunday.","They went home by train."]},{"label":"have → had","form":"had","hint":"Irregular: had lunch, had a great time.","examples":["We had a great time.","I had fish for dinner.","Jack had a busy week."]},{"label":"negative","form":"didn't","hint":"didn't + verb, with no -ed: didn't go, didn't like.","examples":["I didn't go to work.","She didn't like the hotel.","We didn't see the castle."]}],"words":[{"id":"went","en":"went (go)","pt":"foi (ir)","emoji":"🚶"},{"id":"saw","en":"saw (see)","pt":"viu (ver)","emoji":"👀"},{"id":"ate","en":"ate (eat)","pt":"comeu (comer)","emoji":"🍽️"},{"id":"bought","en":"bought (buy)","pt":"comprou (comprar)","emoji":"🛍️"},{"id":"took","en":"took (take)","pt":"pegou, tirou (pegar, tirar)","emoji":"📸"},{"id":"flew","en":"flew (fly)","pt":"voou (voar)","emoji":"🛫"},{"id":"stayed","en":"stayed","pt":"ficou, hospedou-se","emoji":"🏨"},{"id":"visited","en":"visited","pt":"visitou","emoji":"🗺️"},{"id":"walked","en":"walked","pt":"caminhou","emoji":"🥾"},{"id":"trip","en":"trip","pt":"viagem","emoji":"🧳"},{"id":"flight","en":"flight","pt":"voo","emoji":"✈️"},{"id":"souvenir","en":"souvenir","pt":"lembrancinha","emoji":"🎁"},{"id":"tram","en":"tram","pt":"bonde","emoji":"🚋"},{"id":"view","en":"view","pt":"vista","emoji":"🌄"},{"id":"amazing","en":"amazing","pt":"incrível","emoji":"✨"}],"chunks":[{"en":"How was your trip?","pt":"Como foi a viagem?"},{"en":"It was amazing!","pt":"Foi incrível!"},{"en":"The best part was…","pt":"A melhor parte foi…"},{"en":"The worst part was…","pt":"A pior parte foi…"},{"en":"We had a great time.","pt":"A gente se divertiu muito."},{"en":"I didn't have time to…","pt":"Não tive tempo de…"}],"social":{"skill":"Tell someone about a trip","tip":"When someone asks How was your trip?, give a short answer first: It was amazing! Then say The best part was… and maybe one bad thing: The worst part was…","dialogue":[{"who":"Jack","line":"Welcome back, Nina! ___","gap":"How was your trip?","options":["How was your trip?","Where is your trip?","When is your flight?"]},{"who":"Nina","line":"___ Lisbon is so beautiful.","gap":"It was amazing!","options":["It was amazing!","It is tomorrow!","I was born there!"]},{"who":"Jack","line":"Great! Tell me everything."},{"who":"Nina","line":"We walked a lot and we took the old yellow tram. ___ the food. The custard tarts were fantastic!","gap":"The best part was","options":["The best part was","The worst part was","I didn't like"]},{"who":"Jack","line":"Ha! And the worst part?"},{"who":"Nina","line":"The hills! My legs were very tired. And it rained one day, so we didn't go to the beach."},{"who":"Jack","line":"Oh no! But ___, right?","gap":"you had a great time","options":["you had a great time","you have a new job","you went to bed"]},{"who":"Nina","line":"Yes, we did! I want to go back next year."}]},"mistakes":[{"wrong":"I didn't went to the beach.","options":["I didn't go to the beach.","I didn't goed to the beach.","I not went to the beach."],"right":"I didn't go to the beach.","why":"Depois de didn't o verbo volta à forma base: didn't go."},{"wrong":"I went in the beach.","options":["I went to the beach.","I went at the beach.","I gone to the beach."],"right":"I went to the beach.","why":"Com go / went usamos to para o destino: went to the beach."},{"wrong":"Yesterday I visit my brother.","options":["Yesterday I visited my brother.","Yesterday I visiting my brother.","Yesterday I am visit my brother."],"right":"Yesterday I visited my brother.","why":"No passado, verbos regulares ganham -ed: visited."},{"wrong":"We goed to Lisbon in June.","options":["We went to Lisbon in June.","We wented to Lisbon in June.","We gone to Lisbon in June."],"right":"We went to Lisbon in June.","why":"Go é irregular: o passado é went."},{"wrong":"We made a lot of photos.","options":["We took a lot of photos.","We maked a lot of photos.","We taked a lot of photos."],"right":"We took a lot of photos.","why":"'Tirar fotos' é take photos (passado: took), não make."},{"wrong":"We knew a lot of places in Lisbon.","options":["We visited a lot of places in Lisbon.","We knowed a lot of places in Lisbon.","We met a lot of places in Lisbon."],"right":"We visited a lot of places in Lisbon.","why":"'Conhecer um lugar' é visit ou see, não know."}],"pron":{"focus":"-ed: three sounds","tip":"Regular past verbs end in -ed, but -ed has three sounds: /t/ (walked), /d/ (stayed) and /ɪd/ (visited). Only after t or d is -ed an extra syllable. Listen and sort.","type":"sort","buckets":["/t/ walked","/d/ stayed","/ɪd/ visited"],"items":[{"text":"walked","say":"walked","bucket":"/t/ walked"},{"text":"cooked","say":"cooked","bucket":"/t/ walked"},{"text":"watched","say":"watched","bucket":"/t/ walked"},{"text":"stopped","say":"stopped","bucket":"/t/ walked"},{"text":"played","say":"played","bucket":"/d/ stayed"},{"text":"called","say":"called","bucket":"/d/ stayed"},{"text":"rained","say":"rained","bucket":"/d/ stayed"},{"text":"lived","say":"lived","bucket":"/d/ stayed"},{"text":"wanted","say":"wanted","bucket":"/ɪd/ visited"},{"text":"needed","say":"needed","bucket":"/ɪd/ visited"},{"text":"started","say":"started","bucket":"/ɪd/ visited"},{"text":"waited","say":"waited","bucket":"/ɪd/ visited"}]},"practiceSentences":["We went to Lisbon in June","I visited my brother last month","We had a great time","She didn't like the hotel","The best part was the food","We took a lot of photos","I didn't go to the beach","They stayed in a small hotel","It rained on Sunday","How was your trip"],"readingTime":{"text":"Three days in Lisbon (Nina's travel blog)\nLast June, my friend Bia and I went to Lisbon, in Portugal. We flew from Brazil and stayed in a small hotel in the old town.\nOn the first day, we walked a lot. Lisbon has a lot of hills, so my legs were very tired at night! We took the famous yellow tram, number 28. It was slow, but the views were amazing.\nOn the second day, we visited Belém, by the river, and ate the famous Portuguese custard tarts. They were warm and delicious!\nOn the third day, it rained. We didn't go to the beach, but we listened to fado music in a small restaurant. It was a bit sad, but beautiful.\nThe best part? The food, of course! The worst part? The hills!","questions":[{"prompt":"What was slow?","options":["the tram","the music","the flight"],"correct":"the tram"},{"prompt":"What happened on the third day?","options":["It rained.","They flew home.","They ate custard tarts."],"correct":"It rained."}]},"quiz":[{"prompt":"Last year we ___ to Italy.","options":["went","go","goed"],"correct":"went","explain":"Go is irregular: went."},{"prompt":"I ___ my grandmother on Sunday.","options":["visited","visit","visiting"],"correct":"visited","explain":"Regular verb in the past: + -ed."},{"prompt":"She didn't ___ the hotel.","options":["like","liked","likes"],"correct":"like","explain":"After didn't, use the base verb: like."},{"prompt":"We ___ a great time in Lisbon.","options":["had","have","haved"],"correct":"had","explain":"Have is irregular: had."},{"prompt":"The past of see is…","options":["saw","seed","seen"],"correct":"saw","explain":"see → saw (I saw the castle)."},{"prompt":"We ___ a lot of photos.","options":["took","made","did"],"correct":"took","explain":"take photos → took photos."},{"prompt":"Your friend asks: How was your trip? You say…","options":["It was amazing! The best part was the food.","It is amazing! The best part is tomorrow.","Yes, I went."],"correct":"It was amazing! The best part was the food.","explain":"The trip is in the past: It was… The best part was…"}],"writingPrompt":{"prompt":"Write about a trip you remember: where you went, what you did, and the best part.","help":["Last year I went to…","I stayed in / with…","We visited / saw / ate…","The best part was…"],"words":50}},
  {"n":16,"module":4,"id":"syl-a1-16","title":"Did you…? Telling a story","emoji":"📖","description":"Ask past questions with did, give short answers and tell a short story","goals":["I can ask past questions with Did you…?","I can give short answers: Yes, I did. / No, I didn't.","I can ask Where did you go? and What did you do?","I can tell a short story with first, then and in the end, and react to a story."],"grammarTip":"To ask about the past, use did + person + verb: Did you sleep well? Where did you go? The verb doesn't change: Did you go? (not Did you went?). Short answers: Yes, I did. / No, I didn't.","rules":[{"label":"Yes / No questions","form":"Did","hint":"Did + person + verb? Did you…? Did she…?","examples":["Did you have a good weekend?","Did Jack find his keys?","Did they like the film?"]},{"label":"Wh- questions: Where did…?","form":"Where","hint":"Question word + did + person + verb.","examples":["Where did you go on Saturday?","Where did she lose her phone?","Where did you stay in Lisbon?"]},{"label":"short answers","form":"didn't","hint":"Yes, I did. / No, I didn't. Don't repeat the verb.","examples":["No, I didn't.","No, she didn't.","No, we didn't."]},{"label":"telling a story","form":"Then","hint":"First… Then… After that… In the end…","examples":["Then I called my sister.","Then we took a taxi.","Then she saw her bag."]}],"words":[{"id":"lost","en":"lost (lose)","pt":"perdeu (perder)","emoji":"😟"},{"id":"found","en":"found (find)","pt":"encontrou (encontrar)","emoji":"🔍"},{"id":"called","en":"called","pt":"ligou","emoji":"📞"},{"id":"said","en":"said (say)","pt":"disse (dizer)","emoji":"💬"},{"id":"gave","en":"gave (give)","pt":"deu (dar)","emoji":"🎁"},{"id":"left","en":"left (leave)","pt":"deixou, saiu (deixar, sair)","emoji":"🚪"},{"id":"happened","en":"happened","pt":"aconteceu","emoji":"❗"},{"id":"first","en":"first","pt":"primeiro","emoji":"1️⃣"},{"id":"then","en":"then","pt":"então, depois","emoji":"➡️"},{"id":"afterthat","en":"after that","pt":"depois disso","emoji":"⏭️"},{"id":"suddenly","en":"suddenly","pt":"de repente","emoji":"⚡"},{"id":"intheend","en":"in the end","pt":"no final","emoji":"🏁"},{"id":"worried","en":"worried","pt":"preocupado","emoji":"😰"},{"id":"surprised","en":"surprised","pt":"surpreso","emoji":"😲"},{"id":"lucky","en":"lucky","pt":"sortudo, com sorte","emoji":"🍀"}],"chunks":[{"en":"Oh no! Then what?","pt":"Ah, não! E aí?"},{"en":"What happened next?","pt":"E o que aconteceu depois?"},{"en":"Really? You're joking!","pt":"Sério? Tá brincando!"},{"en":"Lucky you!","pt":"Que sorte a sua!"},{"en":"Did you find it?","pt":"Você encontrou?"},{"en":"What a story!","pt":"Que história!"}],"social":{"skill":"React to a story","tip":"When a friend tells you a story, show interest. Say Oh no! or Really? and ask Then what? or What happened next? At the end, say Lucky you! or What a story!","dialogue":[{"who":"Omar","line":"Mei, did I tell you about my phone?"},{"who":"Mei","line":"No! What happened?"},{"who":"Omar","line":"On Saturday I went to the park with Leila. Then I looked in my pocket, and my phone wasn't there!"},{"who":"Mei","line":"___","gap":"Oh no! Then what?","options":["Oh no! Then what?","Lucky you!","Nice to meet you!"]},{"who":"Omar","line":"I went back to the park, but it was dark. I looked and looked."},{"who":"Mei","line":"___","gap":"Did you find it?","options":["Did you find it?","Do you like it?","Did you buy it?"]},{"who":"Omar","line":"No, I didn't. But then I called my number from Sara's phone, and a woman answered. She found it under a bench!"},{"who":"Mei","line":"Really? ___","gap":"Lucky you!","options":["Lucky you!","Oh no!","Excuse me!"]},{"who":"Omar","line":"Yes! In the end, Leila gave her a drawing to say thank you."},{"who":"Mei","line":"Aw, ___","gap":"what a story!","options":["what a story!","what a pity!","what time is it?"]}]},"mistakes":[{"wrong":"Did you went to the party?","options":["Did you go to the party?","Did you goed to the party?","Went you to the party?"],"right":"Did you go to the party?","why":"Com did, o verbo fica na forma base: Did you go?"},{"wrong":"You liked the film?","options":["Did you like the film?","Do you liked the film?","Did you liked the film?"],"right":"Did you like the film?","why":"Pergunta no passado precisa de did + verbo base: Did you like…?"},{"wrong":"Where you went on Saturday?","options":["Where did you go on Saturday?","Where did you went on Saturday?","Where you did go on Saturday?"],"right":"Where did you go on Saturday?","why":"Ordem da pergunta: Where + did + you + verbo base."},{"wrong":"Did you see it? – No, I don't.","options":["Did you see it? – No, I didn't.","Did you see it? – No, I not.","Did you see it? – No, I didn't saw."],"right":"Did you see it? – No, I didn't.","why":"Resposta curta no passado: Yes, I did. / No, I didn't."},{"wrong":"What did happen?","options":["What happened?","What did happened?","What happen?"],"right":"What happened?","why":"Quando what é o sujeito, não usamos did: What happened?"},{"wrong":"I losted my phone.","options":["I lost my phone.","I loosed my phone.","I lossed my phone."],"right":"I lost my phone.","why":"Lose é irregular: o passado é lost."}],"pron":{"focus":"Do you…? or Did you…?","tip":"Listen to the start of the question. Did has a d at the end, so Did you is a bit longer than Do you. Is it about now or the past? Listen and choose.","type":"pairs","items":[{"a":"Do you like it?","b":"Did you like it?"},{"a":"Do you work on Sunday?","b":"Did you work on Sunday?"},{"a":"Do they live here?","b":"Did they live here?"},{"a":"Do you see it?","b":"Did you see it?"},{"a":"Do you cook?","b":"Did you cook?"},{"a":"Do we have class?","b":"Did we have class?"},{"a":"Do you call her?","b":"Did you call her?"}]},"practiceSentences":["Did you have a good weekend","Where did you go on Saturday","No, I didn't","Did you find your phone","Then I called my sister","What happened next","In the end, a woman found it","I lost my phone in the park","What did you do last night"],"readingTime":{"text":"Lost and found on the beach\nLast month, Thandi Mokoena, 32, went to a beach in Cape Town, South Africa, with her family. It was a hot, sunny day.\nThey swam in the sea and played with a ball. Then, in the afternoon, Thandi looked at her hand. Her ring wasn't there!\nIt was her grandmother's ring, very old and very special. The family looked in the sand for two hours, but they didn't find it.\nThat night, Thandi posted a message online: 'I lost my grandmother's ring on the beach. Please help!'\nTwo days later, a man called her. His name was Peter. He walked on the beach every morning with a metal detector. 'I found your ring!' he said.\n'I cried,' Thandi said. 'I was so happy.' In the end, she invited Peter to dinner with her family.","questions":[{"prompt":"Where did Thandi lose her ring?","options":["on a beach","in a restaurant","at home"],"correct":"on a beach"},{"prompt":"Who found the ring?","options":["Peter","Thandi's grandmother","Thandi's family"],"correct":"Peter"}]},"quiz":[{"prompt":"___ you see the match last night?","options":["Did","Do","Were"],"correct":"Did","explain":"Past question with a verb (see): Did you…?"},{"prompt":"Where did you ___ on holiday?","options":["go","went","going"],"correct":"go","explain":"After did, use the base verb: go."},{"prompt":"Did Mei call you? – No, she ___.","options":["didn't","doesn't","wasn't"],"correct":"didn't","explain":"Short answer in the past: No, she didn't."},{"prompt":"What ___ you do last weekend?","options":["did","do","were"],"correct":"did","explain":"Last weekend is past: What did you do?"},{"prompt":"The past of find is…","options":["found","finded","find"],"correct":"found","explain":"find → found (irregular)."},{"prompt":"___, I woke up late. Then I ran to the bus.","options":["First","Then","In the end"],"correct":"First","explain":"A story starts with First."},{"prompt":"Your friend says: I lost my keys! You say…","options":["Oh no! Then what?","Lucky you!","Me too, thanks."],"correct":"Oh no! Then what?","explain":"Bad news: Oh no! Then ask for more."},{"prompt":"Your friend says: A man found my phone! You say…","options":["Lucky you!","Oh no!","What a pity!"],"correct":"Lucky you!","explain":"Good news: Lucky you!"}],"writingPrompt":{"prompt":"Write a short story: something good or bad that happened to you. Use first, then and in the end.","help":["Last … I …","First, I…","Then…","In the end, …"],"words":50}},
  {"n":17,"module":4,"id":"syl-a1-17","title":"Review 2: Modules 3–4","emoji":"🔁","description":"Review food, can, now, comparing and the past, and present your last holiday","goals":["I can talk about now, about the past and compare things.","I can ask questions with can, is…-ing, was and did.","I can talk about my last holiday.","I can share my screen and present to the class."],"grammarTip":"Now: am / is / are + -ing (Omar is cooking). Past: was / were and past verbs (I went, I didn't go, Did you go?). Comparing: bigger than, more expensive than, the best. Look for time words: now, yesterday, last year.","rules":[{"label":"now","form":"is","hint":"am / is / are + -ing for right now.","examples":["Mei is playing the piano now.","It is raining in Dublin today.","Omar is cooking for Leila."]},{"label":"past of be","form":"was","hint":"I / he / she / it was. You / we / they were.","examples":["The hotel was very nice.","It was cold last night.","Jack was in London last week."]},{"label":"past: negative","form":"didn't","hint":"didn't + base verb.","examples":["We didn't eat meat on the trip.","I didn't see the castle.","Nina didn't go to work yesterday."]},{"label":"comparing","form":"than","hint":"-er + than, more + adjective + than.","examples":["Taipei is hotter than Dublin.","The train was faster than the bus.","My new phone is better than the old one."]}],"words":[{"id":"breakfast","en":"breakfast","pt":"café da manhã","emoji":"🥐"},{"id":"delicious","en":"delicious","pt":"delicioso","emoji":"😋"},{"id":"price","en":"price","pt":"preço","emoji":"🏷️"},{"id":"size","en":"size","pt":"tamanho","emoji":"📐"},{"id":"swim","en":"swim","pt":"nadar","emoji":"🏊"},{"id":"sunny","en":"sunny","pt":"ensolarado","emoji":"☀️"},{"id":"raining","en":"raining","pt":"chovendo","emoji":"🌧️"},{"id":"cheaper","en":"cheaper","pt":"mais barato","emoji":"💸"},{"id":"thebest","en":"the best","pt":"o melhor","emoji":"🏆"},{"id":"holiday","en":"holiday","pt":"férias","emoji":"🏖️"},{"id":"museum","en":"museum","pt":"museu","emoji":"🏛️"},{"id":"castle","en":"castle","pt":"castelo","emoji":"🏰"},{"id":"screen","en":"screen","pt":"tela","emoji":"🖥️"},{"id":"share","en":"share","pt":"compartilhar","emoji":"🔗"},{"id":"presentation","en":"presentation","pt":"apresentação","emoji":"📊"}],"chunks":[{"en":"Let me share my screen.","pt":"Deixa eu compartilhar minha tela."},{"en":"Can you see my screen?","pt":"Vocês conseguem ver minha tela?"},{"en":"This is a photo of…","pt":"Esta é uma foto de…"},{"en":"Last year I went to…","pt":"No ano passado eu fui para…"},{"en":"Thanks for listening!","pt":"Obrigado(a) pela atenção!"},{"en":"Any questions?","pt":"Alguma pergunta?"}],"social":{"skill":"Present on screen","tip":"Before you start, say Let me share my screen and check: Can you see my screen? Show each photo with This is a photo of… At the end, say Thanks for listening! Any questions?","dialogue":[{"who":"Ana","line":"OK, Jack, it's your turn!"},{"who":"Jack","line":"Thanks! ___ One moment… OK. Can you see it?","gap":"Let me share my screen.","options":["Let me share my screen.","Let me close my camera.","Let me check the time."]},{"who":"Mei","line":"Yes, we can see it."},{"who":"Jack","line":"Great. ___ Kerry, in the south-west of Ireland. My sons and I went there in August.","gap":"This is a photo of","options":["This is a photo of","This is a friend of","There was a photo of"]},{"who":"Omar","line":"It looks beautiful! Was the weather good?"},{"who":"Jack","line":"No, it wasn't! It rained every day. But the views were amazing, and the boys loved the beach."},{"who":"Nina","line":"Did you cook on holiday, Jack?"},{"who":"Jack","line":"No, I didn't. Sean cooked. He's a better cook than me! OK, that's all. ___","gap":"Thanks for listening!","options":["Thanks for listening!","Thanks for cooking!","Nice to meet you!"]},{"who":"Ana","line":"Great job, Jack! ___","gap":"Any questions for Jack?","options":["Any questions for Jack?","Any coffee for Jack?","Where is Jack?"]}]},"mistakes":[{"wrong":"She working now.","options":["She's working now.","She is work now.","She work now."],"right":"She's working now.","why":"Present continuous precisa de be + -ing: She's (she is) working."},{"wrong":"Can you to swim?","options":["Can you swim?","Do you can swim?","Can you swimming?"],"right":"Can you swim?","why":"Depois de can o verbo vem sem to: Can you swim?"},{"wrong":"I'd like a bread, please.","options":["I'd like some bread, please.","I'd like a breads, please.","I like a bread, please."],"right":"I'd like some bread, please.","why":"Bread é incontável: some bread, não a bread."},{"wrong":"Dublin is more cold than Lisbon.","options":["Dublin is colder than Lisbon.","Dublin is more colder than Lisbon.","Dublin is cold than Lisbon."],"right":"Dublin is colder than Lisbon.","why":"Adjetivo curto: -er + than (colder than)."},{"wrong":"Did you went to Paris?","options":["Did you go to Paris?","Do you went to Paris?","You did went to Paris?"],"right":"Did you go to Paris?","why":"Depois de did o verbo fica na forma base: Did you go?"},{"wrong":"How much costs the ticket?","options":["How much is the ticket?","How much the ticket costs?","How much is cost the ticket?"],"right":"How much is the ticket?","why":"Para perguntar o preço: How much is…? (ou How much does it cost?)."}],"pron":{"focus":"Review: small sounds, big differences","tip":"Small sounds change the meaning: was or wasn't, -er or -est, do or did, can or can't. Listen carefully and choose.","type":"pairs","items":[{"a":"It was cheap.","b":"It wasn't cheap."},{"a":"They were late.","b":"They weren't late."},{"a":"the taller boy","b":"the tallest boy"},{"a":"Do you cook?","b":"Did you cook?"},{"a":"We want it.","b":"We wanted it."},{"a":"She can swim.","b":"She can't swim."},{"a":"It's the bigger one.","b":"It's the biggest one."}]},"practiceSentences":["Last summer I went to Kerry","It rained every day","The views were amazing","Let me share my screen","Can you see my screen","This is a photo of my hotel","The train was faster than the bus","We didn't have a car","Mei is playing the piano now"],"readingTime":{"text":"Three readers, three holidays\nPriya, 31, from Mumbai: 'Last October I went to Edinburgh, in Scotland. It was much colder than Mumbai! I visited the castle and walked up a big hill in the city. The best part was the old streets. The worst part? The rain!'\nKofi, 27, from Accra: 'In December my wife and I went to Cape Town. We took the cable car up Table Mountain. It was the most beautiful view of my life! We also saw penguins on a beach. What a surprise!'\nElena, 45, from Milan: 'I went to Iceland in February. It was dark and very cold, but I saw the northern lights. I swam in a hot pool outside, in the snow! Iceland was more expensive than Italy, but it was my best holiday.'\nNow it's your turn: tell us about your last holiday!","questions":[{"prompt":"Who saw penguins?","options":["Kofi","Priya","Elena"],"correct":"Kofi"},{"prompt":"What was the worst part for Priya?","options":["the rain","the food","the castle"],"correct":"the rain"}]},"quiz":[{"prompt":"Look! It ___ now.","options":["is snowing","snows","snowed"],"correct":"is snowing","explain":"Right now: is + -ing."},{"prompt":"Last year we ___ to Portugal.","options":["went","go","are going"],"correct":"went","explain":"Last year is past: went."},{"prompt":"Is there ___ milk in the fridge?","options":["any","a","many"],"correct":"any","explain":"Milk is uncountable. Questions: any."},{"prompt":"Mei ___ play the piano. She plays every day.","options":["can","can't","is"],"correct":"can","explain":"Ability: can + verb."},{"prompt":"The train was ___ than the bus.","options":["faster","more fast","fastest"],"correct":"faster","explain":"Fast is short: faster than."},{"prompt":"___ you visit the museum?","options":["Did","Were","Was"],"correct":"Did","explain":"Past question with a verb (visit): Did you…?"},{"prompt":"You want to start your presentation. You say…","options":["Let me share my screen.","Let me see your screen.","Share me the screen."],"correct":"Let me share my screen.","explain":"Let me share my screen = I want to show you my screen."},{"prompt":"You finish your presentation. You say…","options":["Thanks for listening! Any questions?","Nice to meet you!","How was your weekend?"],"correct":"Thanks for listening! Any questions?","explain":"At the end: thank people and ask for questions."}],"writingPrompt":{"prompt":"Project: My last holiday. Write about your last holiday for a short presentation: where you went, who you were with, what you did and how it was.","help":["Last … I went to…","I was with…","We visited / ate / saw…","The best part was…"],"words":60}},
  {"n":18,"module":5,"id":"syl-a1-18","title":"Plans and invitations","emoji":"🗓️","description":"Talk about your plans with going to, and invite friends, say yes or say no politely","goals":["I can talk about my plans with going to.","I can ask What are you going to do…?","I can invite someone with Would you like to…?","I can say yes or no to an invitation politely."],"grammarTip":"For plans, use am / is / are + going to + verb: I'm going to travel. For the negative, add not: She's not going to work. To invite someone, say Would you like to + verb? To say yes, say I'd love to!","rules":[{"label":"plan","form":"going to","hint":"am / is / are + going to + verb.","examples":["I'm going to visit my brother.","Nina is going to buy a bike.","We're going to watch the match."]},{"label":"no plan","form":"not going to","hint":"Add not after am / is / are.","examples":["I'm not going to work on Saturday.","Jack's not going to cook tonight.","We're not going to travel this year."]},{"label":"invite","form":"Would you like to","hint":"Would you like to + verb? It's a polite invitation.","examples":["Would you like to come to my party?","Would you like to have dinner with us?","Would you like to watch a film on Friday?"]},{"label":"say yes","form":"I'd love to","hint":"The happy answer to an invitation.","examples":["I'd love to!","Thanks, I'd love to.","I'd love to come!"]}],"words":[{"id":"plan","en":"plan","pt":"plano","emoji":"📝"},{"id":"goal","en":"goal","pt":"meta, objetivo","emoji":"🎯"},{"id":"tomorrow","en":"tomorrow","pt":"amanhã","emoji":"📅"},{"id":"nextweek","en":"next week","pt":"semana que vem","emoji":"🗓️"},{"id":"nextyear","en":"next year","pt":"ano que vem","emoji":"🎆"},{"id":"thisweekend","en":"this weekend","pt":"neste fim de semana","emoji":"🛋️"},{"id":"invite","en":"invite","pt":"convidar","emoji":"✉️"},{"id":"party","en":"party","pt":"festa","emoji":"🎉"},{"id":"trip","en":"trip","pt":"viagem","emoji":"🧳"},{"id":"savemoney","en":"save money","pt":"economizar dinheiro","emoji":"💰"},{"id":"getfit","en":"get fit","pt":"entrar em forma","emoji":"🏃"},{"id":"movehouse","en":"move house","pt":"mudar de casa","emoji":"🏠"},{"id":"busy","en":"busy","pt":"ocupado(a)","emoji":"⏳"},{"id":"free","en":"free (not busy)","pt":"livre, disponível","emoji":"🆓"}],"chunks":[{"en":"Would you like to…?","pt":"Você gostaria de…?"},{"en":"I'd love to!","pt":"Eu adoraria!"},{"en":"Sorry, I can't.","pt":"Desculpa, não posso."},{"en":"I'm going to…","pt":"Eu vou… (plano)"},{"en":"What are you going to do this weekend?","pt":"O que você vai fazer neste fim de semana?"},{"en":"Maybe next time!","pt":"Fica para a próxima!"}],"social":{"skill":"Invite someone, accept and say no politely","tip":"To invite, say Would you like to…? To say yes, say I'd love to! To say no, say Sorry, I can't and give a reason: I'm going to work.","dialogue":[{"who":"Emily","line":"Hi, Omar! Are you busy this weekend?"},{"who":"Omar","line":"Well, I'm going to work a night shift on Saturday. Why?"},{"who":"Emily","line":"It's my birthday on Sunday. ___","gap":"Would you like to come to my party?","options":["Would you like to come to my party?","Do you like parties?","What are you going to do?"]},{"who":"Omar","line":"___ What time is it?","gap":"I'd love to!","options":["I'd love to!","Sorry, I can't.","No, thank you."]},{"who":"Emily","line":"At four o'clock, at my house. Sara and Leila can come too!"},{"who":"Omar","line":"Great, thanks. Leila loves parties."},{"who":"Emily","line":"And would you like to play tennis on Monday?"},{"who":"Omar","line":"___ I'm going to work on Monday too.","gap":"Sorry, I can't.","options":["Sorry, I can't.","I'd love to!","Yes, please."]},{"who":"Emily","line":"No problem. ___","gap":"Maybe next time!","options":["Maybe next time!","Nice to meet you!","Happy birthday!"]}]},"mistakes":[{"wrong":"I go to travel next month.","options":["I'm going to travel next month.","I going to travel next month.","I'm go to travel next month."],"right":"I'm going to travel next month.","why":"Para planos: am / is / are + going to + verbo."},{"wrong":"She going to buy a car.","options":["She's going to buy a car.","She go to buy a car.","She's going buy a car."],"right":"She's going to buy a car.","why":"Não esqueça o is (she's) antes de going to."},{"wrong":"Are you going to traveling?","options":["Are you going to travel?","Do you going to travel?","Are you going traveling to?"],"right":"Are you going to travel?","why":"Depois de going to, o verbo fica na forma base, sem -ing."},{"wrong":"Would you like go to the cinema?","options":["Would you like to go to the cinema?","Would you like going to cinema?","Would you to like go to the cinema?"],"right":"Would you like to go to the cinema?","why":"Would you like + to + verbo."},{"wrong":"I would love!","options":["I'd love to!","I love to!","I'd love!"],"right":"I'd love to!","why":"Para aceitar um convite: I'd love to! (com to no final)."},{"wrong":"Would you like to come in my house on Saturday?","options":["Would you like to come to my house on Saturday?","Would you like to come at my house on Saturday?","Would you like come to my house on Saturday?"],"right":"Would you like to come to my house on Saturday?","why":"Com come e go usamos to para o destino: come to my house."}],"pron":{"focus":"No extra 'ee' at the end of words","tip":"Brazilians often add a little 'ee' sound at the end of words, so cook sounds like cookie. Stop the word on the last consonant. Listen: which word do you hear?","type":"pairs","items":[{"a":"cook","b":"cookie"},{"a":"Jack","b":"Jackie"},{"a":"bag","b":"baggy"},{"a":"dog","b":"doggy"},{"a":"luck","b":"lucky"},{"a":"milk","b":"milky"},{"a":"stick","b":"sticky"}]},"practiceSentences":["I'm going to visit my brother","Nina is going to play volleyball","We're not going to work on Sunday","What are you going to do tomorrow","Would you like to come to my party","I'd love to, thank you","Sorry, I can't go on Friday","Mei is going to learn Spanish next year","Are you going to travel this summer"],"readingTime":{"text":"Big plans at 65: Rosa's walk to Machu Picchu\nRosa Martín is 65 years old. She's from Mexico City, and she's a retired teacher.\nThis year Rosa is going to do something new. She's going to walk the Inca Trail in Peru, to Machu Picchu.\nThe walk is about four days long, and the mountains are very high. “I'm not going to walk fast,” says Rosa. “I'm going to walk slowly and enjoy it.”\nNow she's getting ready. Every morning she walks for an hour in a park near her home. On Saturdays she climbs a big hill with her friend Lupe.\nIs Lupe going to go to Peru too? “No, she isn't,” Rosa laughs. “But she's going to watch my videos every night!”\nAnd Rosa's next plan? “I'd love to see the Northern Lights in Norway. Maybe next year!”","questions":[{"prompt":"How is Rosa going to walk?","options":["slowly","fast","with Lupe"],"correct":"slowly"},{"prompt":"What is Lupe going to do?","options":["watch Rosa's videos","walk the Inca Trail","visit Norway"],"correct":"watch Rosa's videos"}]},"quiz":[{"prompt":"Next week I ___ going to visit my brother.","options":["am","is","are"],"correct":"am","explain":"With I we use am: I'm going to…"},{"prompt":"Jack ___ going to cook tonight. He's going to order a pizza.","options":["isn't","doesn't","not"],"correct":"isn't","explain":"The negative of is going to is isn't going to."},{"prompt":"What ___ you going to do this weekend?","options":["are","do","is"],"correct":"are","explain":"Questions with going to use am / is / are: What are you going to do?"},{"prompt":"A friend invites you to the cinema and you want to go. You say…","options":["I'd love to!","I'd like.","Sorry, I can't."],"correct":"I'd love to!","explain":"I'd love to! is a happy yes to an invitation."},{"prompt":"You can't go to a party. You say…","options":["Sorry, I can't. I'm going to work.","I'd love to!","Yes, I'm going to the party."],"correct":"Sorry, I can't. I'm going to work.","explain":"Say Sorry, I can't and give a reason."},{"prompt":"You want to invite a friend. You say…","options":["Would you like to have lunch with me?","Do you like lunch with me?","You want lunch with me?"],"correct":"Would you like to have lunch with me?","explain":"Would you like to + verb is a polite invitation."},{"prompt":"'Learn to swim this year' is a…","options":["goal","party","trip"],"correct":"goal","explain":"A goal is something you want to do in the future."}],"writingPrompt":{"prompt":"Write about your plans for this year: three things you're going to do and one thing you're not going to do.","help":["This year I'm going to…","I'm also going to…","I'm not going to…","I'd love to… one day."],"words":40}},
  {"n":19,"module":5,"id":"syl-a1-19","title":"Advice, health and rules","emoji":"🩺","description":"Talk about health problems, give advice with should and talk about rules with have to","goals":["I can say what's wrong: I have a headache.","I can give advice with should and shouldn't.","I can talk about rules with have to and don't have to.","I can ask What's the matter? and wish someone well."],"grammarTip":"For advice, use should + verb: You should rest. The negative is shouldn't. For rules and things that are necessary, use have to + verb (he / she has to). Don't have to means it isn't necessary. For 'it's not allowed', say can't.","rules":[{"label":"good idea","form":"should","hint":"should + verb, the same for everyone.","examples":["You should drink a lot of water.","You should see a doctor.","Visitors should try the street food."]},{"label":"bad idea","form":"shouldn't","hint":"shouldn't = should not.","examples":["You shouldn't go to work today.","He shouldn't eat so much sugar.","You shouldn't walk in the rain."]},{"label":"necessary","form":"have to","hint":"A rule or something necessary. He / she has to.","examples":["You have to wear a helmet.","Nurses have to work at night.","I have to get up at six."]},{"label":"not necessary","form":"don't have to","hint":"You can, but it isn't necessary.","examples":["You don't have to pay. It's free.","We don't have to work on Sunday.","Students don't have to wear a uniform."]}],"words":[{"id":"headache","en":"headache","pt":"dor de cabeça","emoji":"🤕"},{"id":"sorethroat","en":"sore throat","pt":"dor de garganta","emoji":"😷"},{"id":"cold","en":"a cold","pt":"um resfriado","emoji":"🤧"},{"id":"fever","en":"fever","pt":"febre","emoji":"🌡️"},{"id":"stomachache","en":"stomachache","pt":"dor de barriga","emoji":"🤢"},{"id":"toothache","en":"toothache","pt":"dor de dente","emoji":"🦷"},{"id":"tired","en":"tired","pt":"cansado(a)","emoji":"🥱"},{"id":"doctor","en":"doctor","pt":"médico(a)","emoji":"🩺"},{"id":"medicine","en":"medicine","pt":"remédio","emoji":"💊"},{"id":"rest","en":"rest","pt":"descansar","emoji":"🛌"},{"id":"advice","en":"advice","pt":"conselho(s)","emoji":"💡"},{"id":"rule","en":"rule","pt":"regra","emoji":"📜"},{"id":"fine","en":"fine","pt":"multa","emoji":"💸"},{"id":"wear","en":"wear","pt":"usar, vestir (roupa)","emoji":"👕"}],"chunks":[{"en":"What's the matter?","pt":"O que houve?"},{"en":"I don't feel well.","pt":"Não estou me sentindo bem."},{"en":"You should…","pt":"Você deveria…"},{"en":"You don't have to…","pt":"Você não precisa…"},{"en":"I hope you feel better soon.","pt":"Espero que você melhore logo."},{"en":"Take care!","pt":"Se cuida!"}],"social":{"skill":"Ask what's wrong, give advice and wish someone well","tip":"If a friend looks ill, ask What's the matter? Give advice with You should… At the end, say I hope you feel better soon or Take care!","dialogue":[{"who":"Omar","line":"Hi, Jack. You don't look well. ___","gap":"What's the matter?","options":["What's the matter?","What do you do?","Where are you from?"]},{"who":"Jack","line":"I have a terrible headache and a sore throat."},{"who":"Omar","line":"Oh no. ___ drink a lot of water and hot tea.","gap":"You should","options":["You should","You don't have to","You shouldn't"]},{"who":"Jack","line":"Tea? I'm Irish. I drink tea all day!"},{"who":"Omar","line":"Good! And you shouldn't go to work tomorrow."},{"who":"Jack","line":"But I have to work. I have a big tour at ten."},{"who":"Omar","line":"Can a friend do the tour? You should stay in bed."},{"who":"Jack","line":"OK, you're right. I'm going to call my friend Declan."},{"who":"Omar","line":"Good idea. ___","gap":"I hope you feel better soon.","options":["I hope you feel better soon.","Have a nice trip.","Congratulations!"]},{"who":"Jack","line":"Thanks, Omar. ___","gap":"Take care!","options":["Take care!","Get well soon!","I don't feel well!"]}]},"mistakes":[{"wrong":"You should to drink water.","options":["You should drink water.","You should drinking water.","You shoulds drink water."],"right":"You should drink water.","why":"Depois de should, o verbo vem sem to."},{"wrong":"I am with headache.","options":["I have a headache.","I am a headache.","I'm with a headache."],"right":"I have a headache.","why":"Para dores e doenças usamos have: I have a headache."},{"wrong":"She have to work at night.","options":["She has to work at night.","She haves to work at night.","She have work at night."],"right":"She has to work at night.","why":"Com he / she / it usamos has to."},{"wrong":"You don't should eat that.","options":["You shouldn't eat that.","You not should eat that.","You should don't eat that."],"right":"You shouldn't eat that.","why":"O negativo de should é shouldn't, sem don't."},{"wrong":"You don't have to smoke here. It's a hospital.","options":["You can't smoke here. It's a hospital.","You don't have smoke here. It's a hospital.","You haven't to smoke here. It's a hospital."],"right":"You can't smoke here. It's a hospital.","why":"Don't have to = não precisa. Para 'é proibido', use can't."},{"wrong":"Good improvements!","options":["Get well soon!","Get better fast you!","Improve yourself!"],"right":"Get well soon!","why":"Para desejar melhoras: Get well soon! ou I hope you feel better soon."}],"pron":{"focus":"should / shouldn't · have to / don't have to","tip":"In shouldn't, the t is very weak: listen for the n sound, should-n. In have to, have sounds like 'haf'. Listen and choose the sentence you hear.","type":"pairs","items":[{"a":"You should go.","b":"You shouldn't go."},{"a":"You should eat it.","b":"You shouldn't eat it."},{"a":"He should call her.","b":"He shouldn't call her."},{"a":"We should wait.","b":"We shouldn't wait."},{"a":"You have to pay.","b":"You don't have to pay."},{"a":"I have to go.","b":"I don't have to go."},{"a":"We have to wear a uniform.","b":"We don't have to wear a uniform."}]},"practiceSentences":["You should drink a lot of water","You shouldn't go to work today","I have to get up at six","We don't have to pay for the museum","What's the matter, Jack","I have a terrible headache","You should see a doctor","Nurses have to work at night","I hope you feel better soon"],"readingTime":{"text":"A visitor's guide to Singapore\nSingapore is a small country and a big city in Southeast Asia. It's hot all year, and it rains a lot, so you should always carry an umbrella.\nGetting around: the MRT trains are fast and clean. But you can't eat or drink on the trains. If you do, you have to pay a fine!\nFood: you should eat at a hawker centre. A hawker centre has a lot of small food stalls, and the food is cheap and very good. Try chicken rice!\nRules: Singapore is famous for its rules. You shouldn't drop rubbish in the street, and you can't buy chewing gum in the shops.\nMoney: you don't have to carry a lot of cash. You can pay by card almost everywhere.\nClothes: you should wear light clothes. But take a jacket too: the shopping malls and cinemas are very cold inside!","questions":[{"prompt":"Why should you carry an umbrella?","options":["It rains a lot.","It's cold.","The trains are slow."],"correct":"It rains a lot."},{"prompt":"What can't you do on the MRT trains?","options":["eat or drink","pay by card","wear a jacket"],"correct":"eat or drink"}]},"quiz":[{"prompt":"I have a cold. — You ___ stay at home and rest.","options":["should","shouldn't","don't have to"],"correct":"should","explain":"Should gives advice: it's a good idea."},{"prompt":"You ___ eat so much sugar. It's bad for your teeth.","options":["shouldn't","should","have to"],"correct":"shouldn't","explain":"Shouldn't = it's a bad idea."},{"prompt":"Omar is a nurse. He ___ work at night some weeks.","options":["has to","have to","should to"],"correct":"has to","explain":"With he / she we say has to."},{"prompt":"The museum is free. You ___ pay.","options":["don't have to","have to","should"],"correct":"don't have to","explain":"Don't have to = it isn't necessary."},{"prompt":"Your friend looks ill. You ask…","options":["What's the matter?","What's your job?","What are you going to do?"],"correct":"What's the matter?","explain":"What's the matter? asks about a problem."},{"prompt":"Your friend has a fever. At the end of the call, you say…","options":["I hope you feel better soon.","Congratulations!","Nice to meet you."],"correct":"I hope you feel better soon.","explain":"We wish an ill person well: I hope you feel better soon."},{"prompt":"Your tooth hurts. You have a…","options":["toothache","headache","sore throat"],"correct":"toothache","explain":"tooth + ache = toothache."}],"writingPrompt":{"prompt":"A friend is going to visit your city. Write tips for them: what they should do, what they shouldn't do, and one rule.","help":["You should visit…","You should try…","You shouldn't…","You have to / You don't have to…"],"words":40}},
  {"n":20,"module":5,"id":"syl-a1-20","title":"Experiences: Have you ever…?","emoji":"🌍","description":"Ask and answer about life experiences with Have you ever…? and ask for details","goals":["I can ask Have you ever…? about experiences.","I can answer Yes, I have or No, I've never…","I can ask How many times…?","I can ask for details: When was that? What was it like?"],"grammarTip":"To ask about experiences in your life, say Have you ever + participle? Have you ever been to Peru? Answer Yes, I have or No, I haven't. I've never… For the details, use the past: When was that? It was amazing!","rules":[{"label":"question","form":"Have you ever","hint":"Have you ever + participle (been, eaten, seen)?","examples":["Have you ever been to Canada?","Have you ever eaten sushi?","Have you ever ridden a horse?"]},{"label":"yes","form":"Yes, I have","hint":"A short answer. Then give details in the past.","examples":["Yes, I have. It was great.","Yes, I have. I loved it!","Yes, I have, but only once."]},{"label":"no","form":"never","hint":"I've never + participle.","examples":["No, I've never been there.","I've never tried it.","Nina has never seen snow."]},{"label":"details","form":"was","hint":"Ask and answer about the details in the past.","examples":["When was that?","What was it like?","It was amazing!"]}],"words":[{"id":"been","en":"been (go)","pt":"ido, estado (ir)","emoji":"🧳"},{"id":"eaten","en":"eaten (eat)","pt":"comido (comer)","emoji":"🍣"},{"id":"seen","en":"seen (see)","pt":"visto (ver)","emoji":"👀"},{"id":"tried","en":"tried (try)","pt":"experimentado (experimentar)","emoji":"🥄"},{"id":"ridden","en":"ridden (ride)","pt":"andado, montado (andar a cavalo/de bicicleta)","emoji":"🐎"},{"id":"swum","en":"swum (swim)","pt":"nadado (nadar)","emoji":"🏊"},{"id":"met","en":"met (meet)","pt":"conhecido (conhecer alguém)","emoji":"🤝"},{"id":"climbed","en":"climbed (climb)","pt":"escalado (escalar, subir)","emoji":"🧗"},{"id":"flown","en":"flown (fly)","pt":"voado (voar)","emoji":"✈️"},{"id":"won","en":"won (win)","pt":"ganhado (ganhar)","emoji":"🏆"},{"id":"once","en":"once","pt":"uma vez","emoji":"1️⃣"},{"id":"twice","en":"twice","pt":"duas vezes","emoji":"✌️"},{"id":"howmanytimes","en":"How many times?","pt":"Quantas vezes?","emoji":"🔢"},{"id":"experience","en":"experience","pt":"experiência","emoji":"🌟"}],"chunks":[{"en":"Have you ever…?","pt":"Você já…?"},{"en":"Yes, I have. / No, I haven't.","pt":"Sim, já. / Não, nunca."},{"en":"I've never…","pt":"Eu nunca…"},{"en":"When was that?","pt":"Quando foi isso?"},{"en":"What was it like?","pt":"Como foi?"},{"en":"How many times?","pt":"Quantas vezes?"}],"social":{"skill":"Ask for details about an experience","tip":"When a friend says Yes, I have, don't stop there. Ask for details: When was that? What was it like? Then answer their question too.","dialogue":[{"who":"Mei","line":"Jack, have you ever been to Asia?"},{"who":"Jack","line":"Yes, I have. I went to Japan once."},{"who":"Mei","line":"Really? ___","gap":"When was that?","options":["When was that?","Where are you from?","What time is it?"]},{"who":"Jack","line":"In 2018, with my sons. Sean was only seven."},{"who":"Mei","line":"___","gap":"What was it like?","options":["What was it like?","What do you like?","Would you like to?"]},{"who":"Jack","line":"It was amazing! But I didn't like the fish for breakfast. What about you? ___ to Ireland?","gap":"Have you ever been","options":["Have you ever been","Have you ever lived","Have you ever eaten"]},{"who":"Mei","line":"No, I haven't. I've never been to Europe. But I'd love to go!"},{"who":"Jack","line":"You should come to Dublin. I can be your tour guide!"},{"who":"Mei","line":"___","gap":"That's a great idea!","options":["That's a great idea!","I hope you feel better soon.","Nice to meet you."]}]},"mistakes":[{"wrong":"Have you ever go to Paris?","options":["Have you ever been to Paris?","Have you ever went to Paris?","Have you ever going to Paris?"],"right":"Have you ever been to Paris?","why":"Depois de Have you ever, use o particípio: been, eaten, seen."},{"wrong":"You have ever eaten sushi?","options":["Have you ever eaten sushi?","You ever have eaten sushi?","Have ever you eaten sushi?"],"right":"Have you ever eaten sushi?","why":"Na pergunta, have vem antes de you."},{"wrong":"I never have been to Asia.","options":["I've never been to Asia.","I have been never to Asia.","I haven't never been to Asia."],"right":"I've never been to Asia.","why":"Never fica entre have e o particípio, e não se usa com outro não: I've never been."},{"wrong":"Have you ever seen snow? — Yes, I did.","options":["Have you ever seen snow? — Yes, I have.","Have you ever seen snow? — Yes, I do.","Have you ever seen snow? — Yes, I am."],"right":"Have you ever seen snow? — Yes, I have.","why":"A resposta curta usa have: Yes, I have / No, I haven't."},{"wrong":"How much times have you been there?","options":["How many times have you been there?","How many time have you been there?","How much time have you been there?"],"right":"How many times have you been there?","why":"Para contar vezes: How many times (com times no plural)."},{"wrong":"It was a experience amazing.","options":["It was an amazing experience.","It was a amazing experience.","It was an experience amazing."],"right":"It was an amazing experience.","why":"O adjetivo vem antes do substantivo, e antes de som de vogal usamos an."}],"pron":{"focus":"-ed endings: no extra 'e'","tip":"Most -ed endings don't add a new syllable: cooked is one syllable (cook-t), not coo-ked. We add a syllable (/ɪd/) only after t or d: visited, needed. Listen and sort.","type":"sort","buckets":["/t/ (cooked)","/d/ (played)","/ɪd/ (visited)"],"items":[{"text":"worked","say":"worked","bucket":"/t/ (cooked)"},{"text":"watched","say":"watched","bucket":"/t/ (cooked)"},{"text":"danced","say":"danced","bucket":"/t/ (cooked)"},{"text":"stopped","say":"stopped","bucket":"/t/ (cooked)"},{"text":"tried","say":"tried","bucket":"/d/ (played)"},{"text":"lived","say":"lived","bucket":"/d/ (played)"},{"text":"climbed","say":"climbed","bucket":"/d/ (played)"},{"text":"travelled","say":"travelled","bucket":"/d/ (played)"},{"text":"wanted","say":"wanted","bucket":"/ɪd/ (visited)"},{"text":"needed","say":"needed","bucket":"/ɪd/ (visited)"},{"text":"started","say":"started","bucket":"/ɪd/ (visited)"},{"text":"decided","say":"decided","bucket":"/ɪd/ (visited)"}]},"practiceSentences":["Have you ever been to Ireland","I've never eaten Japanese food","Nina has never seen snow","Have you ever met a famous person","When was that","What was it like","Jack has been to Japan once","How many times have you been there","Omar has never ridden a horse","Have you ever climbed a mountain"],"readingTime":{"text":"Safari in Kenya: a first-timer's guide\nHave you ever seen a lion in the wild? On a safari in Kenya, you can!\nWhere should you go? Many visitors go to the Maasai Mara. It's a big park in the south-west of Kenya.\nWhat can you see? Lions, elephants, giraffes and zebras. From July to October, millions of animals cross the Mara River. It's called the Great Migration.\nJoseph is a safari guide in the Mara. “I've seen the migration many times,” he says, “but it's always amazing.”\nHave you ever slept in a tent? On safari you can sleep in a tent camp. At night you can hear the animals!\nTip: you should get up early. The animals are very active in the morning, and the light is beautiful for photos.","questions":[{"prompt":"When can you see the Great Migration?","options":["from July to October","in December","every morning"],"correct":"from July to October"},{"prompt":"What does Joseph say about the migration?","options":["It's always amazing.","He has never seen it.","It's boring now."],"correct":"It's always amazing."}]},"quiz":[{"prompt":"Have you ever ___ sushi?","options":["eaten","eat","ate"],"correct":"eaten","explain":"After Have you ever we use the participle: eaten."},{"prompt":"Have you ever been to Canada? — Yes, I ___.","options":["have","did","am"],"correct":"have","explain":"The short answer repeats have: Yes, I have."},{"prompt":"I've ___ been to Asia. I'd love to go!","options":["never","ever","no"],"correct":"never","explain":"I've never + participle = not one time in my life."},{"prompt":"Your friend says: I went to Kenya! You want details. You ask…","options":["What was it like?","What do you like?","Are you going to Kenya?"],"correct":"What was it like?","explain":"What was it like? asks for details about an experience."},{"prompt":"___ times have you been to the beach this year?","options":["How many","How much","How long"],"correct":"How many","explain":"We count times: How many times?"},{"prompt":"The participle of see is…","options":["seen","saw","seed"],"correct":"seen","explain":"see → saw (past) → seen (participle)."},{"prompt":"Have you ever ___ a horse?","options":["ridden","rode","ride"],"correct":"ridden","explain":"ride → rode → ridden."}],"writingPrompt":{"prompt":"Write about your experiences: two things you have done and one thing you have never done. Say when it was and what it was like.","help":["I've been to…","It was…","I've never…","I'd love to… one day."],"words":50}},
  {"n":21,"module":5,"id":"syl-a1-21","title":"Travel: polite requests","emoji":"✈️","description":"Make polite requests at the airport, hotel and restaurant, and solve problems politely","goals":["I can ask for things politely with Could I…?","I can ask people to do things with Could you…?","I can explain a problem politely with I'm afraid…","I can use words for the airport, the hotel and the restaurant."],"grammarTip":"Could I + verb? asks for something for you: Could I have the bill, please? Could you + verb? asks another person to do something: Could you call a taxi, please? To talk about a problem politely, start with I'm afraid…","rules":[{"label":"for me","form":"Could I","hint":"Could I + verb… please? You want something.","examples":["Could I have the bill, please?","Could I see the menu, please?","Could I have a window seat?"]},{"label":"for you to do","form":"Could you","hint":"Could you + verb… please? Another person does it.","examples":["Could you call a taxi for me?","Could you repeat that, please?","Could you help me with my bag?"]},{"label":"a problem","form":"I'm afraid","hint":"A polite start for bad news or a problem.","examples":["I'm afraid my room is very cold.","I'm afraid the shower doesn't work.","I'm afraid this isn't my order."]}],"words":[{"id":"passport","en":"passport","pt":"passaporte","emoji":"🛂"},{"id":"boardingpass","en":"boarding pass","pt":"cartão de embarque","emoji":"🎟️"},{"id":"gate","en":"gate","pt":"portão de embarque","emoji":"🚪"},{"id":"flight","en":"flight","pt":"voo","emoji":"✈️"},{"id":"delayed","en":"delayed","pt":"atrasado (voo)","emoji":"⏰"},{"id":"luggage","en":"luggage","pt":"bagagem","emoji":"🧳"},{"id":"reservation","en":"reservation","pt":"reserva","emoji":"📋"},{"id":"checkin","en":"check in","pt":"fazer check-in","emoji":"🛎️"},{"id":"roomkey","en":"room key","pt":"chave do quarto","emoji":"🔑"},{"id":"towel","en":"towel","pt":"toalha","emoji":"🧺"},{"id":"aircon","en":"air conditioning","pt":"ar-condicionado","emoji":"❄️"},{"id":"menu","en":"menu","pt":"cardápio","emoji":"📖"},{"id":"bill","en":"the bill","pt":"a conta","emoji":"🧾"},{"id":"missflight","en":"miss a flight","pt":"perder um voo","emoji":"🏃"}],"chunks":[{"en":"Could I have…, please?","pt":"Eu poderia ter / Me dá…, por favor?"},{"en":"Could you…, please?","pt":"Você poderia…, por favor?"},{"en":"I'm afraid…","pt":"Sinto muito, mas… / Infelizmente…"},{"en":"I have a reservation.","pt":"Tenho uma reserva."},{"en":"Could I have the bill, please?","pt":"A conta, por favor."},{"en":"No problem.","pt":"Sem problema."}],"social":{"skill":"Solve a problem politely","tip":"Start a problem with I'm afraid… and stay calm. Then ask for help with Could you…? or Could I…? Say please and thank you.","dialogue":[{"who":"Receptionist","line":"Reception, good evening. How can I help you?"},{"who":"Nina","line":"Hello, this is room 305. ___ the air conditioning doesn't work.","gap":"I'm afraid","options":["I'm afraid","I'd love to,","Would you like"]},{"who":"Receptionist","line":"Oh, I'm sorry about that. Someone can fix it tomorrow morning."},{"who":"Nina","line":"Hmm, it's very hot in here. ___ give me a different room, please?","gap":"Could you","options":["Could you","Could I","Should you"]},{"who":"Receptionist","line":"Of course. Room 412 is free. Here's your new key."},{"who":"Nina","line":"Thank you! And ___ have a late check-out tomorrow?","gap":"could I","options":["could I","could you","would you like to"]},{"who":"Receptionist","line":"Yes, you can check out at one o'clock."},{"who":"Nina","line":"Perfect. And ___ call a taxi for me at one, please?","gap":"could you","options":["could you","could I","should I"]},{"who":"Receptionist","line":"No problem. Have a good night!"}]},"mistakes":[{"wrong":"I want the bill.","options":["Could I have the bill, please?","Could you have the bill, please?","Could I the bill, please?"],"right":"Could I have the bill, please?","why":"Para pedir com educação: Could I have…, please?"},{"wrong":"Could you to help me?","options":["Could you help me?","Could you helping me?","Could you helps me?"],"right":"Could you help me?","why":"Depois de could, o verbo vem sem to."},{"wrong":"I have a reserve.","options":["I have a reservation.","I have a reserved.","I have reservation."],"right":"I have a reservation.","why":"Reserva de hotel ou restaurante é reservation (com a)."},{"wrong":"I'm afraid the shower no work.","options":["I'm afraid the shower doesn't work.","I'm afraid the shower don't work.","I'm afraid the shower not work."],"right":"I'm afraid the shower doesn't work.","why":"Com it (the shower), o negativo é doesn't work."},{"wrong":"I lost my flight.","options":["I missed my flight.","I lose my flight.","I lost the my flight."],"right":"I missed my flight.","why":"Perder o voo ou o ônibus é miss, não lose."},{"wrong":"Excuse me, you know where is gate 12?","options":["Excuse me, where is gate 12?","Excuse me, where gate 12 is?","Excuse me, where are gate 12?"],"right":"Excuse me, where is gate 12?","why":"Na pergunta com where, is vem antes: Where is gate 12?"}],"pron":{"focus":"No extra 'ee': one syllable or two?","tip":"Don't add an 'ee' sound at the end. Bag is one syllable, not ba-gee. Check is one syllable, not che-kee. Listen and count the syllables.","type":"sort","buckets":["1 syllable (bag)","2 syllables (ticket)"],"items":[{"text":"bag","say":"bag","bucket":"1 syllable (bag)"},{"text":"gate","say":"gate","bucket":"1 syllable (bag)"},{"text":"check","say":"check","bucket":"1 syllable (bag)"},{"text":"map","say":"map","bucket":"1 syllable (bag)"},{"text":"desk","say":"desk","bucket":"1 syllable (bag)"},{"text":"snack","say":"snack","bucket":"1 syllable (bag)"},{"text":"ticket","say":"ticket","bucket":"2 syllables (ticket)"},{"text":"taxi","say":"taxi","bucket":"2 syllables (ticket)"},{"text":"hotel","say":"hotel","bucket":"2 syllables (ticket)"},{"text":"menu","say":"menu","bucket":"2 syllables (ticket)"},{"text":"passport","say":"passport","bucket":"2 syllables (ticket)"},{"text":"coffee","say":"coffee","bucket":"2 syllables (ticket)"}]},"practiceSentences":["Could I have the menu, please","Could you call a taxi for me","I'm afraid my room is very cold","I have a reservation for two nights","Could I have a window seat","Our flight is delayed","Could you help me with my luggage","I'm afraid this isn't my order","Excuse me, where is gate 12"],"readingTime":{"text":"24 hours in Istanbul\nHi, I'm Sofia, and this is my travel blog. Last month I had one day in Istanbul. Here's my day!\n8 am: My hotel was in the old city. At breakfast I asked the waiter, “Could I have some Turkish tea, please?” It was delicious.\n10 am: I visited the Blue Mosque. You have to take off your shoes, and women should cover their hair.\n1 pm: I took a ferry across the Bosphorus to the Asian side. Yes, Istanbul is in Europe and Asia!\n4 pm: A problem! I couldn't find my phone in the Grand Bazaar. I asked a man in a shop, “Could you help me, please?” He was very kind, and we found it!\n8 pm: Dinner by the water, then “Could I have the bill, please?” and back to the hotel, tired and happy.\nMy tip: you should take the ferry. It's cheap and beautiful.","questions":[{"prompt":"What couldn't Sofia find in the Grand Bazaar?","options":["her phone","her passport","her hotel"],"correct":"her phone"},{"prompt":"How did Sofia go to the Asian side?","options":["by ferry","by taxi","by train"],"correct":"by ferry"}]},"quiz":[{"prompt":"___ I have a window seat, please?","options":["Could","Should","Have"],"correct":"Could","explain":"Could I…? is a polite request."},{"prompt":"___ you call a taxi for me, please?","options":["Could","Have","Are"],"correct":"Could","explain":"Could you…? asks another person to do something."},{"prompt":"Your hotel room is cold and the heating doesn't work. You say…","options":["I'm afraid the heating doesn't work.","I'd love to!","The heating is very good."],"correct":"I'm afraid the heating doesn't work.","explain":"I'm afraid… starts a problem politely."},{"prompt":"You finish your dinner and want to pay. You say…","options":["Could I have the bill, please?","Could I have the menu, please?","Would you like to come?"],"correct":"Could I have the bill, please?","explain":"The bill = the paper with the price of your meal."},{"prompt":"At the airport you show your passport and your…","options":["boarding pass","room key","bill"],"correct":"boarding pass","explain":"You need a boarding pass to get on the plane."},{"prompt":"Your flight is not on time. It's…","options":["delayed","early","free"],"correct":"delayed","explain":"A delayed flight leaves late."},{"prompt":"You arrive at a hotel. You say…","options":["Hello, I have a reservation.","Hello, I have a reserve.","Hello, I'm afraid."],"correct":"Hello, I have a reservation.","explain":"A booking at a hotel is a reservation."}],"writingPrompt":{"prompt":"Write a short email to a hotel. Say when you're going to arrive and ask for two things politely.","help":["Dear Sir or Madam,","I have a reservation for…","Could I…, please?","Could you…, please?"],"words":40}},
  {"n":22,"module":5,"id":"syl-a1-22","title":"Review 3: Module 5","emoji":"🧭","description":"Review all the question types of the course and plan a group trip: suggest, agree and disagree","goals":["I can ask questions in the present, past and future.","I can ask Have you ever…? and Could you…?","I can suggest a plan with Why don't we…? and Let's…","I can agree and disagree politely in a group."],"grammarTip":"Every time has its question. Present: Do you…? / Does she…? Past: Did you…? Future plans: Are you going to…? Experiences: Have you ever…? After do, does and did, the verb is in the base form: Did you go?","rules":[{"label":"present","form":"do you","hint":"Habits and facts: (Where) do you + verb?","examples":["Do you work at the weekend?","Where do you live?","What do you usually eat for breakfast?"]},{"label":"past","form":"did you","hint":"Finished time: (Where) did you + base verb?","examples":["Did you have a good weekend?","Where did you go on holiday?","What did you do last night?"]},{"label":"future plan","form":"are you going to","hint":"Plans: (What) are you going to + verb?","examples":["Are you going to travel this year?","What are you going to do tomorrow?","Where are you going to stay?"]},{"label":"experience","form":"Have you ever","hint":"In your life: Have you ever + participle?","examples":["Have you ever been to Peru?","Have you ever tried Turkish tea?","Have you ever lost your passport?"]}],"words":[{"id":"plan","en":"plan","pt":"plano","emoji":"📝"},{"id":"invite","en":"invite","pt":"convidar","emoji":"✉️"},{"id":"advice","en":"advice","pt":"conselho(s)","emoji":"💡"},{"id":"rule","en":"rule","pt":"regra","emoji":"📜"},{"id":"headache","en":"headache","pt":"dor de cabeça","emoji":"🤕"},{"id":"experience","en":"experience","pt":"experiência","emoji":"🌟"},{"id":"been","en":"been (go)","pt":"ido, estado (ir)","emoji":"🧳"},{"id":"tried","en":"tried (try)","pt":"experimentado","emoji":"🥄"},{"id":"flight","en":"flight","pt":"voo","emoji":"✈️"},{"id":"reservation","en":"reservation","pt":"reserva","emoji":"📋"},{"id":"bill","en":"the bill","pt":"a conta","emoji":"🧾"},{"id":"trip","en":"trip","pt":"viagem","emoji":"🗺️"},{"id":"agree","en":"agree","pt":"concordar","emoji":"👍"},{"id":"suggest","en":"suggest","pt":"sugerir","emoji":"🙋"}],"chunks":[{"en":"Why don't we…?","pt":"Por que a gente não…?"},{"en":"Let's…","pt":"Vamos…"},{"en":"I agree.","pt":"Concordo."},{"en":"I'm not sure.","pt":"Não tenho certeza."},{"en":"That sounds great!","pt":"Parece ótimo!"},{"en":"What do you think?","pt":"O que você acha?"}],"social":{"skill":"Suggest, agree and disagree in a group","tip":"To suggest, say Why don't we…? or Let's… To agree, say I agree or That sounds great! To disagree politely, say I'm not sure and give a reason.","dialogue":[{"who":"Jack","line":"So, where should we go for our class trip? What do you think?"},{"who":"Nina","line":"___ go to Dublin? Jack can be our guide!","gap":"Why don't we","options":["Why don't we","Did we","Have we ever"]},{"who":"Omar","line":"___ It's a great idea.","gap":"I agree.","options":["I agree.","I'm not sure.","I'm afraid."]},{"who":"Mei","line":"Hmm, ___ Dublin is very far from Taipei.","gap":"I'm not sure.","options":["I'm not sure.","I agree.","I'd love to!"]},{"who":"Jack","line":"OK. What about a city in Asia? Mei, you can be our guide!"},{"who":"Mei","line":"Oh! Let's go to Taipei. You have to try the bubble tea!"},{"who":"Nina","line":"___ When are we going to go?","gap":"That sounds great!","options":["That sounds great!","Sorry, I can't.","What's the matter?"]},{"who":"Omar","line":"Why don't we go in July? I don't have to work in July."},{"who":"Mei","line":"OK, but you should bring an umbrella. It rains a lot in the summer."}]},"mistakes":[{"wrong":"You like coffee?","options":["Do you like coffee?","Does you like coffee?","Are you like coffee?"],"right":"Do you like coffee?","why":"No presente, a pergunta precisa de do / does."},{"wrong":"Where you went last weekend?","options":["Where did you go last weekend?","Where did you went last weekend?","Where you did go last weekend?"],"right":"Where did you go last weekend?","why":"No passado: did + verbo na forma base (go, não went)."},{"wrong":"What you are going to do tomorrow?","options":["What are you going to do tomorrow?","What you going to do tomorrow?","What do you going to do tomorrow?"],"right":"What are you going to do tomorrow?","why":"Na pergunta, are vem antes de you."},{"wrong":"Have you ever went to Peru?","options":["Have you ever been to Peru?","Did you ever been to Peru?","Have you ever go to Peru?"],"right":"Have you ever been to Peru?","why":"Have you ever + particípio (been)."},{"wrong":"How much costs the ticket?","options":["How much is the ticket?","How much does cost the ticket?","How many is the ticket?"],"right":"How much is the ticket?","why":"Para preço: How much is…? ou How much does it cost?"},{"wrong":"Does she can swim?","options":["Can she swim?","Is she can swim?","Do she can swim?"],"right":"Can she swim?","why":"Com can não usamos do / does: Can she…?"}],"pron":{"focus":"No extra 'ee' at the end (review)","tip":"Remember: stop on the last consonant. Rain has no 'ee' at the end; rainy has. Listen: which word do you hear?","type":"pairs","items":[{"a":"rain","b":"rainy"},{"a":"sun","b":"sunny"},{"a":"wind","b":"windy"},{"a":"fun","b":"funny"},{"a":"cloud","b":"cloudy"},{"a":"salt","b":"salty"},{"a":"hand","b":"handy"},{"a":"rock","b":"rocky"}]},"practiceSentences":["Do you live with your family","Where did you go last weekend","What are you going to do tomorrow","Have you ever tried Turkish tea","Why don't we go to Dublin","I agree, it's a great idea","I'm not sure about that","Could I have the bill, please","How much is the ticket"],"readingTime":{"text":"Three students, three journeys\nWe asked three students: where did you start, and where are you going?\nNina, Porto Alegre: “I started English two years ago. At first I didn't speak in class. I was very shy! Now I read English every day at work. Next year I'm going to take the A2 course, and I'd love to visit Toronto.”\nOmar, Toronto: “I moved to Canada with my family. My daughter Leila speaks English better than me! Have I ever made a mistake? Many times! But that's OK. Mistakes help me learn.”\nMei, Taipei: “I study online every evening after work. Last month I spoke English with a tourist in Taipei for the first time. I was nervous, but it was great. This summer I'm going to go hiking in Japan, and I'm going to speak English there too.”\nWhat about you? Where did you start, and where are you going?","questions":[{"prompt":"Who spoke English with a tourist last month?","options":["Mei","Nina","Omar"],"correct":"Mei"},{"prompt":"What is Nina going to do next year?","options":["take the A2 course","move to Canada","go hiking in Japan"],"correct":"take the A2 course"}]},"quiz":[{"prompt":"___ you like bubble tea?","options":["Do","Does","Are"],"correct":"Do","explain":"Present questions with you use do."},{"prompt":"Where ___ you go last summer?","options":["did","do","are"],"correct":"did","explain":"Last summer is in the past: did + base verb."},{"prompt":"What ___ you going to do on Sunday?","options":["are","do","did"],"correct":"are","explain":"Plans: are you going to…?"},{"prompt":"Have you ever ___ to Kenya?","options":["been","went","go"],"correct":"been","explain":"Have you ever + participle: been."},{"prompt":"You want to suggest a plan. You say…","options":["Why don't we go to the beach?","Why we don't go to the beach?","Did we go to the beach?"],"correct":"Why don't we go to the beach?","explain":"Why don't we + verb? is a suggestion."},{"prompt":"Your friend has a good idea. You say…","options":["I agree.","I'm afraid.","I'm agree."],"correct":"I agree.","explain":"In English we say I agree, without am."},{"prompt":"___ I have the bill, please?","options":["Could","Should","Did"],"correct":"Could","explain":"Could I…? is a polite request."},{"prompt":"You have a cold. Your friend says: You ___ stay in bed.","options":["should","did","are"],"correct":"should","explain":"Should gives advice."}],"writingPrompt":{"prompt":"Project: plan a group trip with your class. Write where you're going to go, when, what you're going to do there, and one tip for the group.","help":["We're going to go to…","We're going to stay…","Why don't we…?","You should bring…"],"words":50}},
  {"n":23,"module":5,"id":"syl-a1-23","title":"Final speaking practice","emoji":"🎤","description":"Give longer answers with the present, past and future together, and get ready for the final speaking test","goals":["I can talk about my life in the present, past and future.","I can make longer answers with because, so and for example.","I can say Let me think… when I need time.","I can ask the question back: What about you?"],"grammarTip":"In a longer answer, mix the times. Present for habits: I usually… Past for finished things: Last week I… Future for plans: Next year I'm going to… Connect your ideas with and, but, because, so and for example.","rules":[{"label":"now: habits","form":"usually","hint":"Present simple for things you do again and again.","examples":["I usually work from home on Mondays.","Omar usually drinks tea in the morning.","We usually have class in the evening."]},{"label":"past","form":"last","hint":"Past simple: last week, last year, last Sunday.","examples":["Last weekend I visited my brother.","I started English last year.","Mei went hiking last Sunday."]},{"label":"future plan","form":"going to","hint":"am / is / are + going to + verb.","examples":["Next year I'm going to travel.","Jack is going to watch a match tomorrow.","We're going to take the A2 course."]},{"label":"reason","form":"because","hint":"Because answers the question Why?","examples":["I study English because I love travelling.","I'm tired because I worked all night.","I like Dublin because it's friendly."]}],"words":[{"id":"because","en":"because","pt":"porque","emoji":"🔗"},{"id":"so","en":"so","pt":"então, por isso","emoji":"➡️"},{"id":"but","en":"but","pt":"mas","emoji":"⚖️"},{"id":"andthen","en":"and then","pt":"e depois","emoji":"⏭️"},{"id":"also","en":"also","pt":"também","emoji":"➕"},{"id":"forexample","en":"for example","pt":"por exemplo","emoji":"💬"},{"id":"first","en":"first","pt":"primeiro","emoji":"1️⃣"},{"id":"afterthat","en":"after that","pt":"depois disso","emoji":"🔜"},{"id":"usually","en":"usually","pt":"geralmente","emoji":"🔁"},{"id":"lastweek","en":"last week","pt":"semana passada","emoji":"⏪"},{"id":"nextyear","en":"next year","pt":"ano que vem","emoji":"⏩"},{"id":"maybe","en":"maybe","pt":"talvez","emoji":"🤷"},{"id":"nervous","en":"nervous","pt":"nervoso(a)","emoji":"😬"}],"chunks":[{"en":"Let me think…","pt":"Deixa eu pensar…"},{"en":"That's a good question.","pt":"Boa pergunta."},{"en":"For example,…","pt":"Por exemplo,…"},{"en":"What about you?","pt":"E você?"},{"en":"I usually…, but last week I…","pt":"Eu geralmente…, mas semana passada eu…"},{"en":"Next year I'm going to…","pt":"No ano que vem eu vou…"}],"social":{"skill":"Buy time, give an example and ask the question back","tip":"Need a few seconds? Say Let me think… or That's a good question. Then give a reason or an example. At the end, ask back: What about you?","dialogue":[{"who":"Teacher Ana","line":"Jack, tell me about your weekends. What do you usually do?"},{"who":"Jack","line":"___ Well, I usually watch football with my sons.","gap":"Let me think.","options":["Let me think.","Let's go.","I'm afraid."]},{"who":"Teacher Ana","line":"And what did you do last weekend?"},{"who":"Jack","line":"On Saturday I took Sean and Liam to a match. ___ we had burgers in the city centre.","gap":"And then","options":["And then","For example","Because"]},{"who":"Teacher Ana","line":"Lovely. What are you going to do next weekend?"},{"who":"Jack","line":"Hmm, ___ Maybe I'm going to cook for my sons. But I'm a terrible cook!","gap":"that's a good question.","options":["that's a good question.","I hope you feel better soon.","nice to meet you."]},{"who":"Teacher Ana","line":"Do you like living in Dublin?"},{"who":"Jack","line":"Yes, I love it because there's a lot to do. ___, you can visit museums, parks and old pubs.","gap":"For example","options":["For example","And then","What about you"]},{"who":"Jack","line":"What about you, Ana? Do you like your city?"}]},"mistakes":[{"wrong":"Yesterday I go to the beach.","options":["Yesterday I went to the beach.","Yesterday I goed to the beach.","Yesterday I am going to the beach."],"right":"Yesterday I went to the beach.","why":"Para o passado, use o verbo no passado: went."},{"wrong":"I went in the beach.","options":["I went to the beach.","I went at the beach.","I gone to the beach."],"right":"I went to the beach.","why":"Com go / went, o destino vem com to: went to the beach."},{"wrong":"I didn't went to work.","options":["I didn't go to work.","I don't went to work.","I didn't going to work."],"right":"I didn't go to work.","why":"Depois de didn't, o verbo fica na forma base."},{"wrong":"I have 30 years.","options":["I'm 30 years old.","I have 30 years old.","I am 30 years."],"right":"I'm 30 years old.","why":"Idade em inglês usa be: I'm 30 (years old)."},{"wrong":"I like because is fun.","options":["I like it because it's fun.","I like because it's fun.","I like it because is fun."],"right":"I like it because it's fun.","why":"O sujeito não some (it's fun), e like precisa de objeto (it)."},{"wrong":"Is very cold in Porto Alegre in July.","options":["It's very cold in Porto Alegre in July.","Very cold in Porto Alegre in July.","Are very cold in Porto Alegre in July."],"right":"It's very cold in Porto Alegre in July.","why":"Frases sobre o tempo precisam de it: It's cold."}],"pron":{"focus":"-s and -ed: no extra syllable","tip":"Liked is one syllable (like-t), not li-ked. Likes is one syllable too. We add a syllable only after t or d (wanted) or after s, z, ch, sh and ge sounds (watches). Listen and count.","type":"sort","buckets":["1 syllable (liked)","2 syllables (wanted)"],"items":[{"text":"liked","say":"liked","bucket":"1 syllable (liked)"},{"text":"likes","say":"likes","bucket":"1 syllable (liked)"},{"text":"played","say":"played","bucket":"1 syllable (liked)"},{"text":"worked","say":"worked","bucket":"1 syllable (liked)"},{"text":"lives","say":"lives","bucket":"1 syllable (liked)"},{"text":"stopped","say":"stopped","bucket":"1 syllable (liked)"},{"text":"wanted","say":"wanted","bucket":"2 syllables (wanted)"},{"text":"needed","say":"needed","bucket":"2 syllables (wanted)"},{"text":"watches","say":"watches","bucket":"2 syllables (wanted)"},{"text":"dances","say":"dances","bucket":"2 syllables (wanted)"},{"text":"started","say":"started","bucket":"2 syllables (wanted)"},{"text":"closes","say":"closes","bucket":"2 syllables (wanted)"}]},"practiceSentences":["I usually work from home on Mondays","Last weekend I visited my brother","Next year I'm going to travel","I love it because it's fun","Let me think for a second","That's a good question","For example, I play the piano","What about you","I was tired, so I stayed home"],"readingTime":{"text":"Five tips for your final speaking test, by Teacher Ana\n1. Don't give one-word answers. If I ask “Do you like your city?”, don't just say “Yes.” Say why: “Yes, because it's friendly and there's a lot to do.”\n2. Give an example: “I love cooking. For example, last Sunday I made a big lunch for my family.”\n3. Use the past, the present and the future: “I usually…, last week I…, and next year I'm going to…”\n4. Do you need time? That's OK! Say “Let me think…” or “That's a good question.”\n5. Ask a question back: “What about you?” A test is a conversation too.\nLast year a student told me, “I was very nervous, but after two minutes I just talked.” That's the best tip of all. Good luck!","questions":[{"prompt":"What can you say when you need time?","options":["Let me think…","Yes.","Good luck!"],"correct":"Let me think…"},{"prompt":"What does tip 3 say?","options":["Use the past, present and future.","Give one-word answers.","Talk only about your city."],"correct":"Use the past, present and future."}]},"quiz":[{"prompt":"Last weekend I ___ my grandparents.","options":["visited","visit","am going to visit"],"correct":"visited","explain":"Last weekend is in the past: visited."},{"prompt":"Next summer I'm going to ___ to Chile.","options":["travel","travelled","travelling"],"correct":"travel","explain":"Going to + base verb."},{"prompt":"Mei ___ plays the piano in the evening.","options":["usually","last","next"],"correct":"usually","explain":"Usually is for habits in the present."},{"prompt":"I love Dublin ___ the people are friendly.","options":["because","so","but"],"correct":"because","explain":"Because gives the reason."},{"prompt":"I was tired, ___ I went to bed early.","options":["so","because","but"],"correct":"so","explain":"So gives the result."},{"prompt":"You need a few seconds to think. You say…","options":["Let me think…","Let's go!","I'm afraid."],"correct":"Let me think…","explain":"Let me think… buys you time."},{"prompt":"You want to give an example. You say…","options":["For example,…","What about you?","I agree."],"correct":"For example,…","explain":"For example introduces an example."},{"prompt":"Your teacher asks: Do you like music? You answer. Then you ask…","options":["What about you?","What's the matter?","Could I have the bill?"],"correct":"What about you?","explain":"What about you? asks the same question back."}],"writingPrompt":{"prompt":"Write about your life: what you usually do, something you did last month and your plans for next year. Use because and for example.","help":["I usually…","Last month I…","Next year I'm going to…","I like… because…"],"words":60}}
];
